INSERT INTO _Locale ("LocaId","LocaText") VALUES ('ArmAstralsurge_short','Astral Surge');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('ArmAstralsurge_long','Regains 3 AE every 2 seconds, three times.');
