INSERT INTO _Locale ("LocaId","LocaText") VALUES ('ArmQuickstep_short','Quickstep');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('ArmQuickstep_long','Agility +2, Dodge +2, Attack +1.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('ArmShadowstep_name','Shadowstep');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('ArmShadowstep_short','Shadowstep');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('ArmShadowstep_long','Dodge +3, Agility +1.');
