INSERT INTO _Locale ("LocaId","LocaText") VALUES ('ArmFrailty_short','Frailty');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('ArmFrailty_long','Strength -3, Constitution -2, Parry -1.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('ArmStarburn_name','Starburn');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('ArmStarburn_short','Starburn');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('ArmStarburn_long','Magic resistance -2 and 1d6 magic damage every 2 seconds, three times.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_wyrm_scale','Heavy Wyrm Scale');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_wyrm_scale','A scale of the Purplewyrm Japhgur, as large as a shield and harder than steel. Murolosh smiths know what to do with it.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_tr_silver_ruff','Silver Ruff of White Fur');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_tr_silver_ruff','The thick silver-white ruff from White Fur''s neck. Too fine for a trophy wall; a bowyer could work it into something you wear.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_tr_darkwolf_pelt','Dark Wolf Pelt');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_tr_darkwolf_pelt','A near-black pelt from one of the big wolves of the wild country. Supple, warm and quiet as a shadow.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_tr_moonmad_pelt','Moon-mad Pelt');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_tr_moonmad_pelt','A grey wolf pelt shot through with silver where the madness took hold. It bristles when anyone nearby casts a spell.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_tr_moon_sinew','Moon-mad Sinew');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_tr_moon_sinew','Sinew from a moon-mad wolf. It hums when drawn tight, like a bowstring that wants to be plucked.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_tr_greymaw_mane','Greymaw''s Mane');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_tr_greymaw_mane','The iron-grey mane of the mad alpha. Even cut loose, it stands on end.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_tr_storm_heart','Stormhowl''s Heartstone');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_tr_storm_heart','A pale stone from the white wolf that ran with the pack. Sparks crawl over it when you close your hand.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_rl_rattel_pelt','Pelt of Duskmane');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_rl_rattel_pelt','The pelt of Duskmane, the old pack-lord of the Rattelshof hills, grey at the muzzle and black down the spine. Hunters say he was never caught because he was never once in a hurry.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_rl_silver_tincture','Aldessia''s Silver Tincture');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_rl_silver_tincture','A stoppered flask of quicksilver-white fluid, labelled in a careful hand: ''Fixes hide, fur and hair against any rot. Do NOT drink.'' Someone drank. The label was revised.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_rl_sunseal','Inquisitor''s Sun-Seal');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_rl_sunseal','A heavy gold seal of the Praios church, blessed so often that magic slides off it. The Grand Inquisitor pressed it into the wax of every warrant he signed.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_rl_cult_cinder','Cinder of the Dragon-Cult');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_rl_cult_cinder','Black ash from the cult''s fire rites, still warm in the pouch. It smells of burnt hair and promises.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_rl_ogre_hide','Ogre Chief''s Hide');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_rl_ogre_hide','A great slab of grey, warty hide from the chief of the Tallon ogres, thick as a door and about as pleasant to touch.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_rl_golem_heart','Golem Heartstone');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_rl_golem_heart','The stone that kept Aldessia''s guardian moving: a fist of grey crystal that still twitches toward whoever holds it, waiting for an order.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmSetHRh2_name','Set (Regalia of the Lion Queen): LE +3 for each piece you own (re-equip after finding a piece)');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmSetHRh3_name','Set (Regalia of the Lion Queen): LE +4 for each piece you own; all four: LE +5, Courage +1 (re-equip after finding a piece)');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmSetHRh4_name','Set (Regalia of the Lion Queen): LE +5 for each piece you own; all four: LE +10, Courage +1, Agility +1 (re-equip after finding a piece)');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmSetHFo2_name','Set (Ferolax''s Forge-Panoply): LE +3 for each piece you own (re-equip after finding a piece)');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmSetHFo3_name','Set (Ferolax''s Forge-Panoply): LE +4 for each piece you own; all four: Attack +1, Constitution +1 (re-equip after finding a piece)');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmSetHFo4_name','Set (Ferolax''s Forge-Panoply): LE +5 for each piece you own; all four: Attack +1, Constitution +1, LE +10 (re-equip after finding a piece)');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmSetHGw2_name','Set (Moonwarden''s Raiment): AU +4 for each piece you own (re-equip after finding a piece)');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmSetHGw3_name','Set (Moonwarden''s Raiment): AU +5 for each piece you own; all four: Dexterity +1, Dodge +1 (re-equip after finding a piece)');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmSetHGw4_name','Set (Moonwarden''s Raiment): AU +6 for each piece you own; all four: Dexterity +1, Intuition +1, Dodge +2 (re-equip after finding a piece)');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmSetHTh2_name','Set (The Stolen Grimoire): AE +3 for each piece you own (re-equip after finding a piece)');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmSetHTh3_name','Set (The Stolen Grimoire): AE +4 for each piece you own; all four: Agility +1, Dodge +1 (re-equip after finding a piece)');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmSetHTh4_name','Set (The Stolen Grimoire): AE +3 for each piece you own; all four: Agility +1, Dodge +2, Attack +1 (re-equip after finding a piece)');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmSetWpJerkin_name','Set (The Wolfpack): AU +2 for each piece you own; all four: Dodge +1, Sneak +2 (re-equip after finding a piece)');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmSetMhJerkin_name','Set (The Moonhowl Pack): AU +3 for each piece you own; all four: Dodge +1, Sneak +3, Magic resistance +1 (re-equip after finding a piece)');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmSetTcCuirass_name','Set (Tuskhide): LE +2 for each piece you own; all four: Willpower +2, AU +5 (re-equip after finding a piece)');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmSetTsCuirass_name','Set (Ironshell): LE +3 for each piece you own; all four: Parry +1, Magic resistance +1 (re-equip after finding a piece)');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmSetTwCuirass_name','Set (The Warlord): LE +4 for each piece you own; all four: Attack +1, Parry +1 (re-equip after finding a piece)');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmSetWwRobe_name','Set (Witchweave): AE +2 for each piece you own; all four: Magic resistance +1, Intuition +1 (re-equip after finding a piece)');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmSetWeRobe_name','Set (Emberweave): AE +3 for each piece you own; all four: Magic resistance +2, Cleverness +1 (re-equip after finding a piece)');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_r_cutlass','Whetted Cutlass');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_r_cutlass','Ferdok''s river smugglers keep their cutlasses sharp and their stories blunt. This one has a notch in the guard for every customs man who never found the cargo.\n\nOn hit: +1 damage');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_rezept_r_cutlass','Plans: Whetted Cutlass');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_rezept_r_cutlass','Smithing 3. Makes Whetted Cutlass.\n1D6+3 HP, AT +1\nOn hit: +1 damage\nConsumes: 1 Cutlass, 1 Steel.\nThe source item can be bought again.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_r_ember_hatchet','Ember Hatchet');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_r_ember_hatchet','The Avestrue miller split his kindling with it, and the wood always caught a little too eagerly. After the third burnt shed his wife made him sell it.\n\n8% on hit: Burning');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_rezept_r_ember_hatchet','Plans: Ember Hatchet');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_rezept_r_ember_hatchet','Smithing 3. Makes Ember Hatchet.\n1D6+2 HP, AT -1, PA -2, INI -1\n8% on hit: Burning\nConsumes: 1 Hatchet, 2 Tindermold.\nThe source item can be bought again.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_r_practice_saber','Amazon''s Practice Saber');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_r_practice_saber','A Kurkum training blade: light, quick and forgiving.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_r_watch_cudgel','Cudgel of the Watch');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_r_watch_cudgel','Standard issue for the Ferdok watch. Ask any drunk.\n\n12% on hit: Stun');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_r_keen_bow','Keen Hunting Bow');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_r_keen_bow','A quick short bow with a waxed silk string.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_r_notched_axe','Notched Battle Axe');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_r_notched_axe','Every notch is a story. Most end badly for someone else.\n\n5% on hit: Wound');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_r_balanced_longsword','Balanced Longsword');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_r_balanced_longsword','Weighted a finger behind the guard, as the Rondra temple teaches.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_r_vipers_kiss','Viper''s Kiss');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_r_vipers_kiss','The Cellar Vault rewards those who reach its last chest.\n\n12% on hit: Poison');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_r_walking_staff','Runed Walking Staff');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_r_walking_staff','A pilgrim''s staff with one Hesinde rune burned into the heel.\n\nAE +10');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_r_tinker_xbow','Tinkerer''s Crossbow');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_r_tinker_xbow','A dwarf added a ratchet to the winch. Clever, if noisy.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_r_felling_hatchets','Felling Hatchets');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_r_felling_hatchets','Throwing hatchets with a heavy, off-centre head.\n\n10% on hit: Knockdown');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_r_boar_spear','Boar Spear');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_r_boar_spear','A crossbar below the head stops the beast. Mostly.\n\n12% on hit: Knockdown');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_r_balanced_knives','Balanced Throwing Knives');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_r_balanced_knives','Phex-blessed, they say. They certainly fly true.\n\nOn hit: +1 damage');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_r_icicle_foil','Icicle Foil');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_r_icicle_foil','A blue-white foil that is always cold to the touch.\n\n8% on hit: Cold Shock (Corpofrigo)');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmRHuntersCap_name','Animal Lore +2');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmRHuntersCap_short','Animal Lore +2');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmRHuntersCap_long','Animal Lore +2');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_r_hunters_cap','Owlstone''s Hunting Cap');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_r_hunters_cap','A leather cap with a falcon feather and a skinner''s eye.\n\nAnimal Lore +2');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_r_gambeson','Avestrue Gambeson');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_r_gambeson','Quilted by the village for whoever would stand against the robbers.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_r_soft_boots','Thief''s Soft Boots');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_r_soft_boots','Felt soles. You hear the guard; the guard does not hear you.\n\nPick Pocket +2');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_r_herbalist_gloves','Herbalist''s Gloves');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_r_herbalist_gloves','Stained fingertips, steady hands.\n\nAlchemy +3');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_r_fletcher_bracers','Fletcher''s Bracers');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_r_fletcher_bracers','Scored by a thousand fletching knives.\n\nBowyer +3');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_r_scholar_boots','Scholar''s Travel Boots');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_r_scholar_boots','Embroidered with a rune of study. The left one squeaks.\n\nArcane Lore +5');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_r_smith_apron','Journeyman Smith''s Apron');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_r_smith_apron','Scorched leather with a little hammer stamped on the pocket.\n\nBlacksmith +3');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmRWatchSignet_name','Perception +2, Human Nature +2');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmRWatchSignet_short','Perception +2, Human Nature +2');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmRWatchSignet_long','Perception +2, Human Nature +2');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_r_watch_signet','Watchman''s Signet');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_r_watch_signet','The Ferdok watch notices things. So will you.\n\nPerception +2, Human Nature +2');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmRSquireChain_name','Etiquette +3, Fast Talk +2');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmRSquireChain_short','Etiquette +3, Fast Talk +2');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmRSquireChain_long','Etiquette +3, Fast Talk +2');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_r_squire_chain','Squire''s Chain');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_r_squire_chain','Worn by squires at court. Bow first, then speak.\n\nEtiquette +3, Fast Talk +2');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmRAstralSpring_name','AE +5');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmRAstralSpring_short','AE +5');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmRAstralSpring_long','AE +5');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_r_astral_spring','Ring of the Small Astral Spring');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_r_astral_spring','A moonstone chip that holds a sip of astral power.\n\nAE +5');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmRHearthAmulet_name','LE +2, Treat Wounds +1');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmRHearthAmulet_short','LE +2, Treat Wounds +1');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmRHearthAmulet_long','LE +2, Treat Wounds +1');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_r_hearth_amulet','Amulet of Travia''s Hearth');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_r_hearth_amulet','A tiny tin goose, warm like a kitchen fire.\n\nLE +2, Treat Wounds +1');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmRPhexRing_name','Pick Locks +2');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmRPhexRing_short','Pick Locks +2');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmRPhexRing_long','Pick Locks +2');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_r_phex_ring','Ring of Phex''s Fingers');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_r_phex_ring','The fox on the seal winks if you look at it sideways.\n\nDexterity +1, Pick Locks +2');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmRAvesRing_name','AU +5');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmRAvesRing_short','AU +5');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmRAvesRing_long','AU +5');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_r_aves_ring','Wanderer''s Ring of Aves');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_r_aves_ring','Left at the shrine by a traveller who no longer needed luck.\n\nAU +5');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_r_watch_buckler','Watchman''s Shield');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_r_watch_buckler','Reinforced oak, painted with the Ferdok colours.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_r_hjaldinger_shield','Hjaldinger Round Shield');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_r_hjaldinger_shield','Thorwalian lime wood, rimmed in iron and salt.\n\nAU +10');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_a_lioncub','Lioncub Saber');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_a_lioncub','A Kurkum saber for an Amazon who has drawn blood but not yet earned her lion.\n\n12% on hit: Sundered Guard');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_a_ember_saber','Saber of Embers');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_a_ember_saber','Tulamide fire-steel, folded in the smithies of Khunchom where the forges never cool. The edge glows dull red after every kill, as if remembering home.\n\nAgainst burning foes: +1d6 fire damage\n12% on hit: Burning');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_rezept_a_ember_saber','Plans: Saber of Embers');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_rezept_a_ember_saber','Smithing 8. Makes Saber of Embers.\n1D6+4 HP\nAgainst burning foes: +1d6 fire damage; 12% on hit: Burning\nConsumes: 1 Khunchom Saber, 3 Tindermold, 1 Kosh steel.\nThe source item can be bought again.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_a_bloodletter','Bloodletter');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_a_bloodletter','A bastard sword with grooves cut along both edges by a field surgeon who hated it. ''Every wound it makes,'' he wrote, ''is a wound I cannot close.''\n\n12% on hit: Bleeding');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_rezept_a_bloodletter','Plans: Bloodletter');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_rezept_a_bloodletter','Smithing 10. Makes Bloodletter.\n1D6+5 HP, PA -1, INI -1\n12% on hit: Bleeding\nConsumes: 1 Bastard Sword, 2 Kosh steel.\nThe source item can be bought again.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_a_firuns_kiss','Firun''s Kiss');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_a_firuns_kiss','Forged in a winter so cold the smith lost two fingers to the anvil. He swore Firun himself breathed on the blade, and the frost on it never quite melts.\n\n12% on hit: Cold Shock (Corpofrigo)\nAgainst frozen foes: +2 magic damage');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_rezept_a_firuns_kiss','Plans: Firun''s Kiss');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_rezept_a_firuns_kiss','Smithing 9. Makes Firun''s Kiss.\n1D6+5 HP\n12% on hit: Cold Shock (Corpofrigo); Against frozen foes: +2 magic damage\nConsumes: 1 Partisan, 1 Bear Claw, 1 Kosh steel.\nThe source item can be bought again.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_a_felling_maul','Felling Maul');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_a_felling_maul','Warunk loggers carry hammers like this to drive wedges. Mercenaries noticed that the flanged head drives other things too, mostly knees.\n\n12% on hit: Stun\nAgainst downed foes: +3 damage');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_rezept_a_felling_maul','Plans: Felling Maul');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_rezept_a_felling_maul','Smithing 8. Makes Felling Maul.\n1D6+6 HP, PA -1, INI -1\n12% on hit: Stun; Against downed foes: +3 damage\nConsumes: 1 Warunkian Hammer, 2 Steel.\nThe source item can be bought again.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_a_kosch_ember_axe','Ember Skraja of the Kosch');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_a_kosch_ember_axe','Quenched in the shrine-fire of an Angrosch temple in the Kosch mountains, where the dwarves say every spark is a prayer. This one prays loudly.\n\n12% on hit: Burning');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_rezept_a_kosch_ember_axe','Plans: Ember Skraja of the Kosch');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_rezept_a_kosch_ember_axe','Smithing 10. Makes Ember Skraja of the Kosch.\n1D6+6 HP, AT +1\n12% on hit: Burning\nConsumes: 1 Dwarven Skraja, 3 Tindermold, 1 Dwarven steel.\nThe source item can be bought again.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_a_thunder_splitter','Thunder Stonesplitter');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_a_thunder_splitter','A dwarven stonesplitter caught in its own forge when lightning struck the chimney. The smith refused to rework it: ''It has been blessed. Twice.''\n\n12% on hit: +1d6+2 magic damage');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_rezept_a_thunder_splitter','Plans: Thunder Stonesplitter');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_rezept_a_thunder_splitter','Smithing 11. Makes Thunder Stonesplitter.\n2D6+4 HP, PA -2, INI -1\n12% on hit: +1d6+2 magic damage\nConsumes: 1 Stonesplitter, 1 Glittering Green Eye.\nThe source item can be bought again.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_a_leech_rapier','Leech Rapier');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_a_leech_rapier','From a duelling school that taught one lesson: let your opponent tire first. The hollow, rune-scratched blade drinks a little strength with every touch.\n\n25% on hit: heals the wielder 3 LE');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_rezept_a_leech_rapier','Plans: Leech Rapier');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_rezept_a_leech_rapier','Smithing 8. Makes Leech Rapier.\n1D6+4 HP, AT +1, INI +1\n25% on hit: heals the wielder 3 LE\nConsumes: 1 Rapier, 2 Boar Tusk, 1 Gemstones.\nThe source item can be bought again.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_a_starleech_staff','Starleech Staff');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_a_starleech_staff','A wanderer''s staff studded with bits of fallen star by a hedge-mage who could not afford real ones. Each blow pulls a thread of power back to the bearer anyway.\n\nOn hit: restores 1 AE to the wielder\n10% on hit: Hexed');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_rezept_a_starleech_staff','Plans: Starleech Staff');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_rezept_a_starleech_staff','Bowcraft 6. Makes Starleech Staff.\n1D6+3 HP, PA +2, INI +1\nOn hit: restores 1 AE to the wielder; 10% on hit: Hexed\nConsumes: 1 Heavy Fighting Staff, 1 Crypt-louse Carapace, 1 Gold leaf.\nThe source item can be bought again.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_a_thorn_staff','Peraine''s Thorn');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_a_thorn_staff','A healer''s staff of blackthorn. Every blow it lands mends its bearer.\n\nLE +10\n20% on hit: heals the wielder 4 LE');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_a_ember_longbow','Ember Longbow');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_a_ember_longbow','Resin-soaked yew from the Tallon slopes, cured over a slow fire for a whole winter. Slow to draw, and the arrows leave a trail of sparks.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_rezept_a_ember_longbow','Plans: Ember Longbow');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_rezept_a_ember_longbow','Bowcraft 10. Makes Ember Longbow.\n3D6+4 HP, AT +1, reload 2 CR\nConsumes: 1 Longbow, 2 Tindermold, 1 Improved sinews.\nThe source item can be bought again.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_a_huntress_xbow','Huntress'' Crossbow');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_a_huntress_xbow','Owlstone''s mother built it for hunting from the treeline: a bone stock, a hair trigger and a bolt that arrives a little harder than it should.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_rezept_a_huntress_xbow','Plans: Huntress'' Crossbow');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_rezept_a_huntress_xbow','Bowcraft 7. Makes Huntress'' Crossbow.\n1D6+9 HP, reload 3 CR\nConsumes: 1 Light Crossbow, 1 Improved sinews.\nThe source item can be bought again.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_a_felling_xbow','Felling Crossbow');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_a_felling_xbow','Garethian knights laughed at peasant crossbows until these blunt-nosed bolts began unhorsing them. Now they just do not laugh near peasants.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_rezept_a_felling_xbow','Plans: Felling Crossbow');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_rezept_a_felling_xbow','Bowcraft 8. Makes Felling Crossbow.\n1D6+8 HP, AT +1, reload 4 CR\nConsumes: 1 Light Crossbow, 1 Metal parts.\nThe source item can be bought again.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_a_ogre_feller','Ogre-Feller');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_a_ogre_feller','Too heavy for a man and too short for an ogre. Just right for a dwarf.\n\n15% on hit: Shaken');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_a_viper_fang','Serpent''s Embrace');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_a_viper_fang','An Al''Anfan design: venom runs down the fuller and the pommel unscrews to refill it. They call it an embrace because no one notices it until it is too late to let go.\n\n20% on hit: Poison\nAgainst poisoned foes: +2 poison damage');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_rezept_a_viper_fang','Plans: Serpent''s Embrace');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_rezept_a_viper_fang','Smithing 7. Makes Serpent''s Embrace.\n1D6+2 HP, PA -1\n20% on hit: Poison; Against poisoned foes: +2 poison damage\nConsumes: 1 Heavy Dagger, 2 Venom sac.\nThe source item can be bought again.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_a_thunder_shortsword','Short Sword of Thunder');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_a_thunder_shortsword','A legionary''s short sword etched with a storm-glyph by a Rondra priestess who thought soldiers should hear their blades coming.\n\n12% on hit: +1d6 magic damage');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_rezept_a_thunder_shortsword','Plans: Short Sword of Thunder');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_rezept_a_thunder_shortsword','Smithing 7. Makes Short Sword of Thunder.\n1D6+3 HP, AT +1, PA -1, INI +1\n12% on hit: +1d6 magic damage\nConsumes: 1 Short Sword, 1 Bear Claw.\nThe source item can be bought again.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_a_tide_trident','Efferd''s Trident');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_a_tide_trident','Fished out of the well behind your Ferdok house. Nobody knows how it got there.\n\n12% on hit: Knockdown\n10% on hit: Cold Shock (Corpofrigo)');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmARondraWard_name','Magic resistance +1');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmARondraWard_short','Magic resistance +1');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmARondraWard_long','Magic resistance +1');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_a_rondra_ward','Ward of Rondra');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_a_rondra_ward','Rondra''s lion on a leather shield. Those who carry it do not fall.\n\nMagic resistance +1');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_a_lionheart_helm','Lionheart Helm');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_a_lionheart_helm','A winged helm whose wearer never takes the first step back.\n\nCourage +2');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_a_longshot_bracers','Bracers of the Long Shot');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_a_longshot_bracers','Archer''s arm guards embossed with a falcon.\n\nDexterity +1');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_a_peraine_gloves','Gloves of Peraine');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_a_peraine_gloves','Green-dyed leather blessed by the goddess of healing.\n\nLE +10');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_a_fox_boots','Fox-step Boots');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_a_fox_boots','Iryan leather that remembers every root on the forest floor.\n\nAgility +1, Dodge +1');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_a_astral_robe','Robe of the Astral Tide');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_a_astral_robe','Silver thread woven in the pattern of the Hesinde tide tables.\n\nAE +10, Magic resistance +2');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_a_ingerimm_apron','Apron of Ingerimm');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_a_ingerimm_apron','Fireproof leather from a master of the Murolosh forges.\n\nBlacksmith +6\nImmune to burning');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_a_ironhide_greaves','Ironhide Greaves');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_a_ironhide_greaves','Iron greaves weighted with lead along the shin, made for the Ferdok bridge guard. One drunk cannot push a man in these into the river. Two still can.\n\nConstitution +1\nImmune to knockdown');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_rezept_a_ironhide_greaves','Plans: Ironhide Greaves');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_rezept_a_ironhide_greaves','Smithing 9. Makes Ironhide Greaves.\nLegs 3; metal, encumbrance 0.6\nConstitution +1; Immune to knockdown\nConsumes: 1 Iron Greaves, 2 Steel, 2 Leather strips.\nThe source item can be bought again.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_a_duelist_grips','Duelist''s Grips');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_a_duelist_grips','A Horasian fencing master''s design: heavy leather cuffs that catch a blade on the back of the hand. ''Parry with the steel,'' he taught, ''and with the glove when the steel is late.''\n\nParry +1');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_rezept_a_duelist_grips','Plans: Duelist''s Grips');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_rezept_a_duelist_grips','Smithing 8. Makes Duelist''s Grips.\nArms 3; leather, encumbrance 0.2\nParry +1\nConsumes: 1 Heavy Leather Gloves, 2 Leather strips, 2 Boar Tusk.\nThe source item can be bought again.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_a_ironfist','Ironfist Gauntlets');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_a_ironfist','Combined gauntlets from a Weiden armoury, forged for knights who preferred to hold the line rather than ride at it.\n\nStrength +1');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_rezept_a_ironfist','Plans: Ironfist Gauntlets');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_rezept_a_ironfist','Smithing 10. Makes Ironfist Gauntlets.\nArms 5; metal, encumbrance 0.4\nStrength +1\nConsumes: 1 Gauntlets, 2 Kosh steel.\nThe source item can be bought again.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_a_iryan_greaves','Iryan Half-greaves');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_a_iryan_greaves','Iryan leather is cured in the far south with a resin the Tulamides keep to themselves. Cut to a scout''s pattern, these guard the shin and leave the foot free to run and climb.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_rezept_a_iryan_greaves','Plans: Iryan Half-greaves');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_rezept_a_iryan_greaves','Smithing 8. Makes Iryan Half-greaves.\nLegs 3; leather, encumbrance 0.3\nConsumes: 1 Heavy Leather Greaves, 3 Leather strips, 1 Steel.\nThe source item can be bought again.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_a_ranger_breeches','Ranger''s Reinforced Breeches');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_a_ranger_breeches','The pattern was pinned inside Grimmzahn''s arrow rack, signed by Hagbart, the castle''s last ranger. Dark wolf pelt at the knees and sinew in every seam: he swore they outlasted three pairs of boots and one baron.\n\nDodge +1');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_rezept_a_ranger_breeches','Plans: Ranger''s Reinforced Breeches');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_rezept_a_ranger_breeches','Smithing 8. Makes Ranger''s Reinforced Breeches.\nBelly 1, Legs 3; leather, encumbrance 0.0\nDodge +1\nConsumes: 1 Heavy-duty Leather Pants, 2 Dark Wolf Pelt, 1 Improved sinews.\nThe source item can be bought again.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_a_adept_mantle','Adept''s Shoulder-mantle');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_a_adept_mantle','Stitched by students of a Punin academy who were tired of iron pauldrons ruining their spells. The astral thread hums faintly when a spell is near.\n\nAE +10');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_rezept_a_adept_mantle','Plans: Adept''s Shoulder-mantle');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_rezept_a_adept_mantle','Alchemy 7. Makes Adept''s Shoulder-mantle.\nArms 2; leather, encumbrance 0.1\nAE +10\nConsumes: 1 Leather Shoulder Guards, 2 Firefly Ember Sac.\nThe source item can be bought again.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_a_spellweaver_breeches','Spellweaver''s Breeches');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_a_spellweaver_breeches','Tallon''s magician had these embroidered with runes of clear thought after his apprentice set her own sleeve alight mid-spell. The runes do nothing for fire. They do wonders for concentration.\n\nIntuition +1, Cleverness +1');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_rezept_a_spellweaver_breeches','Plans: Spellweaver''s Breeches');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_rezept_a_spellweaver_breeches','Alchemy 7. Makes Spellweaver''s Breeches.\nLegs 2; cloth, encumbrance 0.0\nIntuition +1, Cleverness +1\nConsumes: 1 Thorwalian Pants, 2 Firefly Ember Sac, 1 Gemstones.\nThe source item can be bought again.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmAUnbowed_name','AU +5');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmAUnbowed_short','AU +5');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmAUnbowed_long','AU +5');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_a_unbowed','Amulet of the Unbowed');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_a_unbowed','A broken chain on a silver thread. You will not kneel.\n\nAU +5');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmAOxRing_name','LE +5');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmAOxRing_short','LE +5');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmAOxRing_long','LE +5');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_a_ox_ring','Ring of the Ox');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_a_ox_ring','A heavy band of black iron set with a golden ox-head.\n\nConstitution +1, LE +5');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmAFletcherRing_name','Bowyer +2, Bow +1');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmAFletcherRing_short','Bowyer +2, Bow +1');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmAFletcherRing_long','Bowyer +2, Bow +1');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_a_fletcher_ring','Fletcher''s Thumb Ring');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_a_fletcher_ring','A horn thumb ring that never slips.\n\nBowyer +5, Bow +1');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmASummonerTorc_name','Helpful Paw +3, Skelettarius +2, Elemental Servant +2, AE +5');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmASummonerTorc_short','Helpful Paw +3, Skelettarius +2, Elemental Servant +2, AE +5');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmASummonerTorc_long','Helpful Paw +3, Skelettarius +2, Elemental Servant +2, AE +5');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_a_summoner_torc','Summoner''s Torc');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_a_summoner_torc','A druidic torc of twisted gold; animals come when it hums.\n\nHelpful Paw +3, Skelettarius +2, Elemental Servant +2, AE +5');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmAClearMind_name','Arcane Lore +3');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmAClearMind_short','Arcane Lore +3');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmAClearMind_long','Arcane Lore +3');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_a_clear_mind','Ring of the Clear Mind');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_a_clear_mind','A Hesinde-blue sapphire that settles the thoughts.\n\nCleverness +1, Intuition +1, Arcane Lore +3');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmASalamanderPhial_name','Magic resistance +1, AE +5');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmASalamanderPhial_short','Magic resistance +1, AE +5');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmASalamanderPhial_long','Magic resistance +1, AE +5');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_a_salamander_phial','Salamander Phial');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_a_salamander_phial','A sealed vial on a chain, holding a single living ember.\n\nMagic resistance +1, AE +5\nImmune to burning');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_a_umbracor_splinter','Splinter of Umbracor''s Heart');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_a_umbracor_splinter','A sliver of the good dragon''s heart, torn loose when the Purplewyrm fell. Where is the rest?\n\nLE +10, AE +10\nImmune to burning');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_s_rondra_reprimand','Rondra''s Reprimand');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_s_rondra_reprimand','A Kurkum saber reforged with dwarven steel and gold leaf. It punishes cowardice and rewards the warrior who presses on.\n\n15% on hit: Sundered Guard\nAgainst downed foes: +1d6 damage\n8% on hit: wielder gains Battle Trance');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_s_coalheart','Coalheart');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_s_coalheart','A two-handed stonesplitter with a core of coal that never cools.\n\nImmune to burning\nAgainst burning foes: +1d6 fire damage\n15% on hit: Burning');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_s_mountain_patience','Mountain''s Patience');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_s_mountain_patience','A dwarven maul reworked from a woodsman''s hammer with steel from the deep forges. The mountain waits, and then it falls on you.\n\n15% on hit: Stun\nAgainst stunned foes: +1d6 damage');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_s_nightsong','Nightsong');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_s_nightsong','A quick elven bow restrung with elf wood and fine sinew. At night its string hums a lullaby, and the creatures of the forest listen.\n\nIntuition +1');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_s_heartseeker','Heartseeker');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_s_heartseeker','A heavy Thorwal war bow. Slow, and it never misses twice.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmSArchonRod_name','Fulminictus +2, Ignifaxius +2');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmSArchonRod_short','Fulminictus +2, Ignifaxius +2');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmSArchonRod_long','Fulminictus +2, Ignifaxius +2');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_s_archon_rod','Archon''s Rod');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_s_archon_rod','Megalon''s old teaching rod. Students learned to dodge it; enemies don''t.\n\nAE +10, Magic resistance +2, Fulminictus +2, Ignifaxius +2\n25% on hit: Hexed\nOn hit: restores 2 AE to the wielder');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_s_phex_whisper','Whisper of Phex');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_s_phex_whisper','Stolen from a Horasian count by someone who left a fox as a calling card.\n\nPick Pocket +2\n15% on hit: Dazed\nAgainst dazed foes: +3 damage');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_s_tusk','Tusk of the Sow-King');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_s_tusk','Carved from the tusk of the boar that ate an Albernian village.\n\n15% on hit: Knockdown\n12% on hit: Bleeding');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_s_thunderbolt','Thunderbolt');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_s_thunderbolt','A dwarven siege crossbow. The bolt arrives before the thunder.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_s_widowmaker','Widowmaker');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_s_widowmaker','A mercenary two-hander with a ricasso wrapped in black leather.\n\n15% on hit: Bleeding\n10% on hit: Knockdown');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_s_sentinel_mail','Mail of the Silver Falls Sentinel');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_s_sentinel_mail','The last sentinel of the castle died standing.\n\nLE +10, Constitution +1\nImmune to knockdown');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_s_thinking_cap','Hesinde''s Thinking Cap');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_s_thinking_cap','A tall hat whose stars rearrange themselves while you think.\n\nAE +10, Intuition +1, Cleverness +1');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_s_dancer_boots','Boots of the Seven-League Dancer');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_s_dancer_boots','Iryan boots whose wearer seems to arrive before setting out.\n\nAgility +2, Dodge +2, AU +10');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_s_forge_grips','Grips of the Forgefather');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_s_forge_grips','Every knuckle is a tiny anvil.\n\nStrength +2, Blacksmith +3');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_s_salamander_scale','Salamander Scale Cuirass');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_s_salamander_scale','Salamander scales riveted over dwarven chain.\n\nLE +10, Constitution +1\nImmune to burning');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_d_gauntlets','Gauntlets of the Mountain King');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_d_gauntlets','Gauntlets of the old Murolosh kings, refolded with steel that only a dwarf of the royal line may hammer. The fingers close by themselves around a haft.\n\nStrength +1');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_rezept_d_gauntlets','Plans: Gauntlets of the Mountain King');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_rezept_d_gauntlets','Smithing 12. Makes Gauntlets of the Mountain King.\nArms 6; metal, encumbrance 0.5\nStrength +1\nConsumes: 1 Dwarven Gauntlets, 2 Dwarven steel, 1 Glittering Green Eye.\nThe source item can be bought again.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_d_sabatons','Stoneroot Sabatons');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_d_sabatons','Plated boots made for the hearthguard who stood at the mountain gate for a century. They root their wearer like a stone that has decided not to move.\n\nAU +10\nImmune to knockdown');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_rezept_d_sabatons','Plans: Stoneroot Sabatons');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_rezept_d_sabatons','Smithing 12. Makes Stoneroot Sabatons.\nLegs 7; metal, encumbrance 0.9\nAU +10; Immune to knockdown\nConsumes: 1 Dwarven Plated Boots, 2 Dwarven steel, 2 Leather strips.\nThe source item can be bought again.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_d_pauldrons','Pauldrons of the Hearthguard');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_d_pauldrons','The pauldrons of the king''s hearthguard, each plate engraved with the name of a guard who fell at his post. There is room left for more names.\n\nLE +10');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_rezept_d_pauldrons','Plans: Pauldrons of the Hearthguard');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_rezept_d_pauldrons','Smithing 11. Makes Pauldrons of the Hearthguard.\nChest 2, Back 2, Arms 3; metal, encumbrance 0.5\nLE +10\nConsumes: 1 Dwarven Shoulder Plates, 1 Dwarven steel, 3 Leather strips.\nThe source item can be bought again.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_d_helm','Helm of the Deep Watch');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_d_helm','A storm cap with a single gem over the brow, worn by the watchers of the deep shafts. The gem catches light where no light should be.\n\nConstitution +1, Courage +1');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_rezept_d_helm','Plans: Helm of the Deep Watch');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_rezept_d_helm','Smithing 12. Makes Helm of the Deep Watch.\nHead 6; metal, encumbrance 1.0\nConstitution +1, Courage +1\nConsumes: 1 Dwarven Storm Cap, 1 Dwarven steel, 1 Glittering Green Eye.\nThe source item can be bought again.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_k_warboots','Kurkum Warboots');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_k_warboots','The plated boots of Kurkum, reforged by an Amazon smith to cover the whole leg. ''A sister who cannot be tripped,'' she said, ''cannot be beaten.''\n\nAU +10');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_rezept_k_warboots','Plans: Kurkum Warboots');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_rezept_k_warboots','Smithing 10. Makes Kurkum Warboots.\nLegs 6; metal, encumbrance 0.8\nAU +10\nConsumes: 1 Kurkumian Plated Boots, 2 Kosh steel, 2 Leather strips.\nUNIQUE: the original cannot be bought again.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmSSecondWind_name','Faster LE regeneration (-3), Faster AU regeneration (-3)');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmSSecondWind_short','Faster LE regeneration (-3), Faster AU regeneration (-3)');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmSSecondWind_long','Faster LE regeneration (-3), Faster AU regeneration (-3)');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_s_second_wind','Ring of the Second Wind');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_s_second_wind','A breath of Rondra''s storm caught in a ring.\n\nFaster LE regeneration (-3), Faster AU regeneration (-3), AU +10');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmSUnshakenMind_name','Magic resistance +3, Willpower +3; Immune to fear, sleep and paralysis');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmSUnshakenMind_short','Magic resistance +3, Willpower +3; Immune to fear, sleep and paralysis');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmSUnshakenMind_long','Magic resistance +3, Willpower +3; Immune to fear, sleep and paralysis');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_s_unshaken_mind','Amulet of the Unshaken Mind');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_s_unshaken_mind','A Psychostabilis glyph sealed in amber.\n\nMagic resistance +3, Willpower +3\nImmune to fear, sleep and paralysis');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmSFalconEye_name','Bow +3, Crossbow +3, Damage +1');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmSFalconEye_short','Bow +3, Crossbow +3, Damage +1');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmSFalconEye_long','Bow +3, Crossbow +3, Damage +1');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_s_falcon_eye','Eye of the Falcon');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_s_falcon_eye','A falcon''s eye of yellow topaz. Through it, everything is in range.\n\nBow +3, Crossbow +3, Damage +1');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_s_angrosch_wall','Wall of Angrosch');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_s_angrosch_wall','A kite shield of dwarven steel. Behind it, you are a mountain.\n\nConstitution +1\nImmune to knockdown');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmSLuckyStar_name','Magic resistance +2');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmSLuckyStar_short','Magic resistance +2');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmSLuckyStar_long','Magic resistance +2');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_s_lucky_star','Ring of the Lucky Star');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_s_lucky_star','Phex''s own star, they say, fell into a gambler''s cup.\n\nDodge +2, Magic resistance +2, Charisma +1');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_w_scale_cuirass','Wyrmscale Cuirass');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_w_scale_cuirass','Scales from the great purple wyrm riveted over plate by smiths who had to work in shifts: the scales stayed hot for a week. Heavy, warm and nearly impenetrable.\n\nLE +10\nImmune to burning');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_rezept_w_scale_cuirass','Plans: Wyrmscale Cuirass');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_rezept_w_scale_cuirass','Smithing 13. Makes Wyrmscale Cuirass.\nChest 6, Belly 7, Back 7, Arms 3, Legs 2; metal, encumbrance 4.8\nLE +10; Immune to burning\nConsumes: 1 Light Plate Armor, 3 Heavy Wyrm Scale, 1 Dwarven steel.\nThe source item can be bought again.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_w_hide_jerkin','Wyrmhide Jerkin');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_w_hide_jerkin','Flexible scales sewn onto leather soaked in dragon blood. It moves like a second skin, and the skin underneath it never feels the cold again.\n\nImmune to burning\nImmune to knockdown');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_rezept_w_hide_jerkin','Plans: Wyrmhide Jerkin');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_rezept_w_hide_jerkin','Smithing 12. Makes Wyrmhide Jerkin.\nChest 5, Belly 5, Back 5, Arms 1; leather, encumbrance 1.7\nImmune to burning; Immune to knockdown\nConsumes: 1 Leather Doublet., 2 Heavy Wyrm Scale, 2 Dragon blood, 4 Leather strips.\nThe source item can be bought again.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_w_blood_robe','Dragonblood Robe');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_w_blood_robe','A battle-mage''s robe steeped in the wyrm''s blood, with one scale sewn over the heart. Mages who wear it dream of flying, and wake angry.\n\nAE +10, Magic resistance +2\nImmune to burning');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_rezept_w_blood_robe','Plans: Dragonblood Robe');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_rezept_w_blood_robe','Alchemy 12. Makes Dragonblood Robe.\nChest 4, Belly 4, Back 4, Arms 1; cloth, encumbrance 1.0\nAE +10, Magic resistance +2; Immune to burning\nConsumes: 1 Robe of the City of Ferdok, 1 Heavy Wyrm Scale, 3 Dragon blood, 2 Gold leaf.\nThe source item can be bought again.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_w_scale_shield','Wyrmscale Shield');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_w_scale_shield','Two great wyrm scales bolted to an iron shield. Fire splashes off it like rain; so, now and then, does a sword.\n\nConstitution +1\nImmune to burning');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_rezept_w_scale_shield','Plans: Wyrmscale Shield');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_rezept_w_scale_shield','Smithing 11. Makes Wyrmscale Shield.\nAT -1, PA +3\nConstitution +1; Immune to burning\nConsumes: 1 Iron Shield, 2 Heavy Wyrm Scale.\nThe source item can be bought again.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmLFangLioness_name','Golden aura');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmLFangLioness_short','Golden aura');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmLFangLioness_long','Golden aura');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_l_fang_lioness','Fang of the Lioness');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_l_fang_lioness','Rondra''s saber, given to the first Queen of Kurkum.\n\nCourage +1\nImmune to knockdown\n20% on hit: Sundered Guard\nAgainst downed foes: +1d6 damage\nAgainst burning foes: +1d6 fire damage\n10% on hit: wielder gains Lion''s Roar');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmLAngroschHammer_name','Spark aura');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmLAngroschHammer_short','Spark aura');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmLAngroschHammer_long','Spark aura');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_l_angrosch_hammer','First-Forge Hammer of Angrosch');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_l_angrosch_hammer','The hammer Angrosch used to forge the first dwarf. It is still warm.\n\nStrength +2\nImmune to burning\n15% on hit: Knockdown\n15% on hit: Burning\nAgainst downed foes: +1d6 fire damage\n8% on hit: wielder gains Iron Skin');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmLSalaMandra_name','Falcon''s-eye aura');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmLSalaMandra_short','Falcon''s-eye aura');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmLSalaMandra_long','Falcon''s-eye aura');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_l_sala_mandra','Bow of Sala Mandra');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_l_sala_mandra','The quick bow of the elven queen who sang the Salamander to sleep.\n\nIntuition +2');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmLEyeHesinde_name','Fulminictus +2, Ignifaxius +2, Armatrutz +1; Astral aura');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmLEyeHesinde_short','Fulminictus +2, Ignifaxius +2, Armatrutz +1; Astral aura');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmLEyeHesinde_long','Fulminictus +2, Ignifaxius +2, Armatrutz +1; Astral aura');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_l_eye_hesinde','Eye of Hesinde');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_l_eye_hesinde','A staff topped with a crystal eye that sees the threads of every spell.\n\nAE +10, Magic resistance +2, Cleverness +1, Intuition +1, Fulminictus +2, Ignifaxius +2, Armatrutz +1\nOn hit: restores 2 AE to the wielder\n20% on hit: Hexed\n8% on hit: wielder gains Astral Surge');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmLPhexLaugh_name','Silver aura');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmLPhexLaugh_short','Silver aura');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmLPhexLaugh_long','Silver aura');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_l_phex_laugh','Phex''s Last Laugh');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_l_phex_laugh','A dragon-tooth dagger stolen from Japhgur himself. Twice.\n\nPick Pocket +2, Agility +1, Dexterity +1\n20% on hit: Dazed\n15% on hit: Wyrm Venom\nAgainst dazed foes: +1d6 damage\n10% on hit: wielder gains Quickstep');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmLWyrmbane_name','Battle aura');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmLWyrmbane_short','Battle aura');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmLWyrmbane_long','Battle aura');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_l_wyrmbane','Wyrmbane');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_l_wyrmbane','The Andergast blade that took the head of the Lindwurm of Gratenfels.\n\nImmune to burning\n15% on hit: Bleeding\n12% on hit: Knockdown\n8% on hit: wielder gains Battle Trance');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmLKurkumAegis_name','Armatrutz aura');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmLKurkumAegis_short','Armatrutz aura');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmLKurkumAegis_long','Armatrutz aura');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_l_kurkum_aegis','Kurkum Aegis');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_l_kurkum_aegis','The shield of the Amazon queens. No blow has ever broken it.\n\nCourage +1, LE +10\nImmune to knockdown');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmLSevenGazes_name','Violet aura');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmLSevenGazes_short','Violet aura');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmLSevenGazes_long','Violet aura');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_l_seven_gazes','Robe of the Seven Gazes');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_l_seven_gazes','Seven eyes are embroidered on it. Some of them blink.\n\nAE regeneration +1, AE +10, Magic resistance +2, Cleverness +1, Intuition +1');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmLHeartUmbracor_name','Frost aura');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmLHeartUmbracor_short','Frost aura');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmLHeartUmbracor_long','Frost aura');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_l_heart_umbracor','Heart of Umbracor');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_l_heart_umbracor','The good dragon''s heart, made whole and sealed in the dwarves'' amulet vault.\n\nCourage +1, Cleverness +1, Intuition +1, Charisma +1, LE +10, AE +10\nImmune to burning');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_m_last_oath','Last Oath of the Dragon-Slayer');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_m_last_oath','A dragonslayer hammer carried through the Fire Falls by the last of its oath-bound wielders.\n\nStrength +1\nImmune to burning\n10% on hit: Knockdown\nAgainst downed foes: +1d6 damage');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_m_ashwarden','Ashwarden''s Mantle');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_m_ashwarden','A light robe that came through the Fire Falls unburnt.\n\nAE +10, Magic resistance +2, Cleverness +1\nImmune to burning');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_m_gatekeeper','Gatekeeper of Gruldur');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_m_gatekeeper','The door-shield of the sealed halls. It has never been passed.\n\nConstitution +2, LE +10\nImmune to knockdown');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmRSpellguard_name','AE +5');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmRSpellguard_short','AE +5');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmRSpellguard_long','AE +5');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_r_spellguard','Spellguard Buckler');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_r_spellguard','A small buckler of rune-carved horn and leather for duellists who also cast. No metal: it does not hinder spellcasting.\n\nAE +5');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmANightfoxBuckler_name','Magic resistance +2');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmANightfoxBuckler_short','Magic resistance +2');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmANightfoxBuckler_long','Magic resistance +2');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_a_nightfox_buckler','Nightfox Buckler');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_a_nightfox_buckler','Blackened ironwood, quiet and light. It turns blades and curses alike. No metal: it does not hinder spellcasting.\n\nDodge +1, Magic resistance +2');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmSMirrorBuckler_name','Magic resistance +1');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmSMirrorBuckler_short','Magic resistance +1');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmSMirrorBuckler_long','Magic resistance +1');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_s_mirror_buckler','Phexian Mirror-Buckler');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_s_mirror_buckler','Lacquered so bright it shines like a mirror; spells glance off it. No metal: it does not hinder spellcasting.\n\nMagic resistance +3, AE +10\nImmune to burning');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_a_hexknives','Hexing Hatchets');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_a_hexknives','Sharpened throwing hatchets, each blade scratched with a curse-rune by a hedge-witch who hated woodcutters. They fly true, and whatever they hit feels the curse before the cut.\n\n15% on hit: Hexed');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_rezept_a_hexknives','Plans: Hexing Hatchets');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_rezept_a_hexknives','Smithing 6. Makes 25 Hexing Hatchets.\n1D6+6 HP\n15% on hit: Hexed\nConsumes: 10 Sharpened Throwing Hatchet, 1 Boar Tusk, 1 Alcohol.\nThe source item can be bought again.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_a_starfall','Starfall Stars');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_a_starfall','Throwing stars polished with powdered silver by a Tulamide juggler who also happened to be an assassin. In flight they flash like falling stars.\n\nOn hit: +1d6 magic damage\n15% on hit: Dazed');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_rezept_a_starfall','Plans: Starfall Stars');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_rezept_a_starfall','Smithing 7. Makes 25 Starfall Stars.\n1D6+0 HP\nOn hit: +1d6 magic damage; 15% on hit: Dazed\nConsumes: 1 Steel, 1 Crypt-louse Carapace.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_s_witchfire','Witchfire Daggers');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_s_witchfire','Balanced daggers with a hollow core of salamander oil. A witch of the southern marshes made them for a lover who left her. They burn whatever they touch, which seems fair.\n\nOn hit: +1d6 fire damage\n15% on hit: Burning');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_rezept_s_witchfire','Plans: Witchfire Daggers');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_rezept_s_witchfire','Smithing 9. Makes 25 Witchfire Daggers.\n1D6+2 HP\nOn hit: +1d6 fire damage; 15% on hit: Burning\nConsumes: 1 Kosh steel, 2 Tindermold.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmASpellthiefDirk_name','AE +5');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmASpellthiefDirk_short','AE +5');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmASpellthiefDirk_long','AE +5');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_a_spellthief_dirk','Spellthief''s Dirk');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_a_spellthief_dirk','A dirk forged for a thieves'' guild that robbed mages. Each cut steals a spark of power, and the guild never once paid for a light.\n\nAE +5\n15% on hit: restores 1 AE to the wielder\n12% on hit: Hexed');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_rezept_a_spellthief_dirk','Plans: Spellthief''s Dirk');
