INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_d_moonsilver','Silver drawn by moonlight. The dead hate it.\n\nAE +5\nAgainst the undead: +1d6+2 magic damage\n12% on hit: Blinding Flash');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_d_kris','Assassin''s Kris');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_d_kris','A wavy Tulamide blade. It strikes the blinded and the unwary.\n\n10% on hit: Wound\nAgainst blinded foes: +1d6 damage\n10% on hit: Wyrm Venom');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_d_athame','Starfire Athame');
