INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_w_moonshadow','Moonshadow Saber');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_w_moonshadow','A saber that seems to slip sideways out of every parry.\n\n12% on hit: wielder gains Shadowstep');
