INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_s_ashblade','Ilsabe''s Khunchom saber, tempered in a burning chapel. It still remembers the fire.\n\nCourage +1\n15% on hit: Burning\nAgainst burning foes: +1d6 fire damage\n8% on hit: wielder gains Battle Trance');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmLDuskarrow_name','Falcon''s-eye aura');
