INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmLDuskarrow_long','Falcon''s-eye aura');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_l_duskarrow','Duskarrow');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_l_duskarrow','Faelwen''s bow, cut from a yew that grew where the moon touches the water. It was strung to sing to the forest, and he taught it to hunt the forest''s own children. Gwendala hears it still: a thin, grieving note beneath the string, the song of a bow that hated every arrow it was made to loose. Hold it gently. It is listening for a kinder hand.\n\nDexterity +1');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_l_oathbreaker','Oathbreaker');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_l_oathbreaker','Sir Wolfhart swore on this blade to defend Grimmzahn, then sold the gate to the orcs.\n\nStrength +1, Courage +1\n15% on hit: Shaken\n12% on hit: Bleeding\nAgainst shaken foes: +1d6 damage');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_s_oath_pavise','Pavise of the Broken Oath');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_s_oath_pavise','Wolfhart''s kite shield. The Grimmzahn crest has been scraped off.\n\nConstitution +1\nImmune to knockdown');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmLLionsbane_name','Sabers +2; Golden aura');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmLLionsbane_short','Sabers +2; Golden aura');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmLLionsbane_long','Sabers +2; Golden aura');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_l_lionsbane','Lionsbane');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_l_lionsbane','Sabeth was cast out of Kurkum for killing a sister in a duel. Rhulana will want this saber back.\n\nAgility +1, Courage +1, Sabers +2\n15% on hit: Sundered Guard\n12% on hit: Wound\nAgainst wounded foes: +1d6 damage\n10% on hit: wielder gains Lion''s Roar');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_l_exile_cleaver','Exile''s Cleaver');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_l_exile_cleaver','Grimbart Ironbeard was banished from Murolosh with this axe. Forgrimm has heard the story; the dwarves do not tell it twice.\n\nStrength +2, Constitution +1\n15% on hit: Knockdown\n15% on hit: Frailty\nAgainst downed foes: +1d6+2 damage\n8% on hit: wielder gains Iron Skin');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmMCrimsonVow_name','Silver aura');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmMCrimsonVow_short','Silver aura');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmMCrimsonVow_long','Silver aura');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_m_crimson_vow','Crimson Vow');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_m_crimson_vow','The Crimson Master''s dirk. Every member of the Circle swore their oath on it, in blood.\n\nAgility +2, Dexterity +1, AE +10\n20% on hit: Bleeding\n15% on hit: Starburn\nAgainst bleeding foes: +1d6+2 damage\nOn hit: restores 1 AE to the wielder\n10% on hit: wielder gains Shadowstep');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_a_klingenhand_gloves','Klingenhand''s Fencing Gloves');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_a_klingenhand_gloves','Thin kid gloves, darned at the knuckles. They have won forty duels.\n\nAttack +1, Parry +1');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmJCrimsonCircle_name','Battle aura');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmJCrimsonCircle_short','Battle aura');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmJCrimsonCircle_long','Battle aura');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_j_crimson_circle','Ring of the Crimson Circle');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_j_crimson_circle','Seven blades engraved around a red stone. Its last owner was the best duelist in the Middenrealm; now it is you.\n\nAttack +1, Parry +1, Agility +1, Courage +1');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmJRkSpectacles_name','Magic resistance +1, Arcane Lore +3');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmJRkSpectacles_short','Magic resistance +1, Arcane Lore +3');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmJRkSpectacles_long','Magic resistance +1, Arcane Lore +3');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_j_rk_spectacles','Rakorium''s Spare Spectacles');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_j_rk_spectacles','Worn on a chain. Through them, magic looks like handwriting, and handwriting looks like magic.\n\nCleverness +1, Intuition +1, Magic resistance +1, Arcane Lore +3');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_a_rk_best_hat','Rakorium''s Best Hat');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_a_rk_best_hat','Not the second-best hat. THE hat. Slightly singed, and it knows things.\n\nAE +10, Cleverness +1, Intuition +1, Magic resistance +2');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmHRh1_name','Sabers +1, AU +3');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmHRh1_short','Sabers +1, AU +3');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmHRh1_long','Sabers +1, AU +3');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_h_rh1','Lion''s Tooth of Kurkum (I)');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_h_rh1','Rhulana: "My mother wore this when she took her lioness oath. I thought it was lost." It waits for the Queen''s regalia.\n\nSabers +1, AU +3');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmHRh2_name','Sabers +1');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmHRh2_short','Sabers +1');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmHRh2_long','Sabers +1');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_h_rh2','Mane of the Lioness (II)');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_h_rh2','Rhulana''s mother''s tooth, bound in a mane of braided gold. She stands a little taller wearing it, and nobody mentions it.\n\nCourage +1, Attack +1, Sabers +1\nSet (Regalia of the Lion Queen): LE +3 for each piece you own (re-equip after finding a piece)');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_rezept_h_rh2','Plans: Mane of the Lioness (II)');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_rezept_h_rh2','Smithing 8. Makes Mane of the Lioness (II).\n\nCourage +1, Attack +1, Sabers +1; Set (Regalia of the Lion Queen): LE +3 for each piece you own (re-equip after finding a piece)\nConsumes: 1 Lion''s Tooth of Kurkum (I), 1 Tatzelwurm Fang, 2 Firefly Ember Sac.\nUNIQUE: the original cannot be bought again.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmHRh3_name','Sabers +2; Golden aura');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmHRh3_short','Sabers +2; Golden aura');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmHRh3_long','Sabers +2; Golden aura');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_h_rh3','Pride of Kurkum (III)');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_h_rh3','Dwarven gold wrapped around a Kurkum oath. ''Rondra hears every word sworn on this,'' says Rhulana, and then she swears quite a lot.\n\nCourage +2, Attack +1, Parry +1, Sabers +2\nSet (Regalia of the Lion Queen): LE +4 for each piece you own; all four: LE +5, Courage +1 (re-equip after finding a piece)');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_rezept_h_rh3','Plans: Pride of Kurkum (III)');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_rezept_h_rh3','Smithing 11. Makes Pride of Kurkum (III).\n\nCourage +2, Attack +1, Parry +1, Sabers +2; Set (Regalia of the Lion Queen): LE +4 for each piece you own; all four: LE +5, Courage +1 (re-equip after finding a piece)\nConsumes: 1 Mane of the Lioness (II), 1 Dwarven steel, 2 Crypt-louse Carapace, 1 Gemstones.\nUNIQUE: the original cannot be bought again.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmHRh4_name','Sabers +2; Golden aura');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmHRh4_short','Sabers +2; Golden aura');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmHRh4_long','Sabers +2; Golden aura');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_h_rh4','Heart of the Lion Queen (IV)');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_h_rh4','A wyrm scale set in the Lion Queen''s gold. The first Queen of Kurkum wore nothing finer; the songs will say Rhulana wore it better.\n\nCourage +3, Attack +1, Parry +1, LE +10, Sabers +2\nImmune to knockdown\nSet (Regalia of the Lion Queen): LE +5 for each piece you own; all four: LE +10, Courage +1, Agility +1 (re-equip after finding a piece)');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_rezept_h_rh4','Plans: Heart of the Lion Queen (IV)');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_rezept_h_rh4','Smithing 13. Makes Heart of the Lion Queen (IV).\n\nCourage +3, Attack +1, Parry +1, LE +10, Sabers +2; Immune to knockdown; Set (Regalia of the Lion Queen): LE +5 for each piece you own; all four: LE +10, Courage +1, Agility +1 (re-equip after finding a piece)\nConsumes: 1 Pride of Kurkum (III), 1 Heavy Wyrm Scale, 3 Gold leaf, 2 Gemstones.\nUNIQUE: the original cannot be bought again.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_lq_helm','Lion Queen''s Crest-Helm');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_lq_helm','A Kurkum helm with a golden lion crest. Part of the Regalia of the Lion Queen.\n\nParry +1');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_lq_cuirass','Lion Queen''s Cuirass');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_lq_cuirass','Gilded plate over red leather. Sabeth stole it when Kurkum cast her out. Part of the Regalia of the Lion Queen.\n\nLE +10, Constitution +1');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_lq_grips','Lion Queen''s Grips');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_lq_grips','Red leather sword-grips with gilded knuckles. Part of the Regalia of the Lion Queen.\n\nAttack +1, Agility +1');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_lq_sabatons','Lion Queen''s Sabatons');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_lq_sabatons','Kurkum plated boots worked with lion claws. Part of the Regalia of the Lion Queen.\n\nAgility +1, Dodge +1\nImmune to knockdown');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmHFo1_name','Blacksmith +2, Two-handed Axes/Maces +1');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmHFo1_short','Blacksmith +2, Two-handed Axes/Maces +1');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmHFo1_long','Blacksmith +2, Two-handed Axes/Maces +1');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_h_fo1','Ferolax''s Hammer-Ring (I)');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_h_fo1','Forgrimm: "My father''s ring. I have worn it since the day he died, and I will wear it until it is worthy of him." It waits for the panoply of Ferolax.\n\nBlacksmith +2, Two-handed Axes/Maces +1');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmHFo2_name','Blacksmith +2');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmHFo2_short','Blacksmith +2');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmHFo2_long','Blacksmith +2');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_h_fo2','Anvil-Ring of Ferolax (II)');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_h_fo2','Reforged on a human anvil. Forgrimm grumbles that the work is sloppy, polishes it every evening, and wears it anyway.\n\nStrength +1, Constitution +1, Blacksmith +2\nSet (Ferolax''s Forge-Panoply): LE +3 for each piece you own (re-equip after finding a piece)');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_rezept_h_fo2','Plans: Anvil-Ring of Ferolax (II)');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_rezept_h_fo2','Smithing 8. Makes Anvil-Ring of Ferolax (II).\n\nStrength +1, Constitution +1, Blacksmith +2; Set (Ferolax''s Forge-Panoply): LE +3 for each piece you own (re-equip after finding a piece)\nConsumes: 1 Ferolax''s Hammer-Ring (I), 2 Kosh steel, 2 Firefly Ember Sac.\nUNIQUE: the original cannot be bought again.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmHFo3_name','LE +5; Aura');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmHFo3_short','LE +5; Aura');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmHFo3_long','LE +5; Aura');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_h_fo3','Forgefire Ring (III)');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_h_fo3','Dwarven steel folded the way Ferolax taught his son, seven times and once more for luck. ''Now that,'' says Forgrimm, ''is a ring.''\n\nStrength +1, Constitution +1, LE +5, Blacksmith +3\nSet (Ferolax''s Forge-Panoply): LE +4 for each piece you own; all four: Attack +1, Constitution +1 (re-equip after finding a piece)');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_rezept_h_fo3','Plans: Forgefire Ring (III)');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_rezept_h_fo3','Smithing 11. Makes Forgefire Ring (III).\n\nStrength +1, Constitution +1, LE +5, Blacksmith +3; Set (Ferolax''s Forge-Panoply): LE +4 for each piece you own; all four: Attack +1, Constitution +1 (re-equip after finding a piece)\nConsumes: 1 Anvil-Ring of Ferolax (II), 2 Dwarven steel, 1 Glittering Green Eye.\nUNIQUE: the original cannot be bought again.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmHFo4_name','Aura');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmHFo4_short','Aura');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmHFo4_long','Aura');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_h_fo4','Ferolax''s Unbroken Oath (IV)');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_h_fo4','Quenched in dragon blood around a sliver of wyrm scale. Ferolax swore to forge this ring and never could. His son did.\n\nStrength +2, Constitution +2, LE +10\nImmune to burning\nSet (Ferolax''s Forge-Panoply): LE +5 for each piece you own; all four: Attack +1, Constitution +1, LE +10 (re-equip after finding a piece)');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_rezept_h_fo4','Plans: Ferolax''s Unbroken Oath (IV)');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_rezept_h_fo4','Smithing 13. Makes Ferolax''s Unbroken Oath (IV).\n\nStrength +2, Constitution +2, LE +10; Immune to burning; Set (Ferolax''s Forge-Panoply): LE +5 for each piece you own; all four: Attack +1, Constitution +1, LE +10 (re-equip after finding a piece)\nConsumes: 1 Forgefire Ring (III), 1 Heavy Wyrm Scale, 2 Dwarven steel, 1 Dragon blood.\nUNIQUE: the original cannot be bought again.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmFxHelm_name','Magic resistance +1');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmFxHelm_short','Magic resistance +1');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmFxHelm_long','Magic resistance +1');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_fx_helm','Ferolax''s Crown-Helm');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_fx_helm','The dragonslayer helm of Ferolax. Grimbart took it into exile. Part of Ferolax''s Forge-Panoply.\n\nConstitution +1, Magic resistance +1');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_fx_plate','Ferolax''s Forge-Plate');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_fx_plate','Dwarven plate with an anvil worked into the chest. Part of Ferolax''s Forge-Panoply.\n\nLE +10, Strength +1');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_fx_gauntlets','Ferolax''s Gauntlets');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_fx_gauntlets','Heavy dwarven gauntlets, still black from his forge. Part of Ferolax''s Forge-Panoply.\n\nAttack +1');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_fx_boots','Ferolax''s Plated Boots');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_fx_boots','Dwarven plated boots that have never taken a step back. Part of Ferolax''s Forge-Panoply.\n\nConstitution +1\nImmune to knockdown');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmHGw1_name','Bow +1, Perception +2');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmHGw1_short','Bow +1, Perception +2');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmHGw1_long','Bow +1, Perception +2');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_h_gw1','Seed of the Moon-Tree (I)');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_h_gw1','Gwendala: "A moon-tree seed. My people plant one for every warden. Someone carried mine all the way to this marsh."\n\nBow +1, Perception +2');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmHGw2_name','Bow +1');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmHGw2_short','Bow +1');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmHGw2_long','Bow +1');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_h_gw2','Song of Sala (II)');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_h_gw2','The moon-tree seed has sprouted inside its silver cage. It hums an elven song at dusk that nobody taught it.\n\nIntuition +1, Dexterity +1, Bow +1\nSet (Moonwarden''s Raiment): AU +4 for each piece you own (re-equip after finding a piece)');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_rezept_h_gw2','Plans: Song of Sala (II)');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_rezept_h_gw2','Bowcraft 8. Makes Song of Sala (II).\n\nIntuition +1, Dexterity +1, Bow +1; Set (Moonwarden''s Raiment): AU +4 for each piece you own (re-equip after finding a piece)\nConsumes: 1 Seed of the Moon-Tree (I), 2 Harpy feathers, 1 Elf wood.\nUNIQUE: the original cannot be bought again.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmHGw3_name','Bow +2; Falcon''s-eye aura');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmHGw3_short','Bow +2; Falcon''s-eye aura');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmHGw3_long','Bow +2; Falcon''s-eye aura');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_h_gw3','Moonwarden''s Oath (III)');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_h_gw3','A moon-tree sapling no longer than a finger. Gwendala says it can see in the dark. She is not joking, and that is the unsettling part.\n\nIntuition +2, Dexterity +1, Dodge +1, Bow +2\nSet (Moonwarden''s Raiment): AU +5 for each piece you own; all four: Dexterity +1, Dodge +1 (re-equip after finding a piece)');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_rezept_h_gw3','Plans: Moonwarden''s Oath (III)');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_rezept_h_gw3','Bowcraft 11. Makes Moonwarden''s Oath (III).\n\nIntuition +2, Dexterity +1, Dodge +1, Bow +2; Set (Moonwarden''s Raiment): AU +5 for each piece you own; all four: Dexterity +1, Dodge +1 (re-equip after finding a piece)\nConsumes: 1 Song of Sala (II), 1 Glittering Green Eye, 1 Elf wood, 1 Improved sinews.\nUNIQUE: the original cannot be bought again.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmHGw4_name','Bow +2; Falcon''s-eye aura');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmHGw4_short','Bow +2; Falcon''s-eye aura');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmHGw4_long','Bow +2; Falcon''s-eye aura');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_h_gw4','Sala Mandra''s Last Song (IV)');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_h_gw4','The moon-tree blossoms around a dragon scale, as in the song of the elven queen who sang the great salamander to sleep. Gwendala knows all the verses now.\n\nIntuition +3, Dexterity +2, Agility +1, Dodge +2, Bow +2\nImmune to poison\nSet (Moonwarden''s Raiment): AU +6 for each piece you own; all four: Dexterity +1, Intuition +1, Dodge +2 (re-equip after finding a piece)');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_rezept_h_gw4','Plans: Sala Mandra''s Last Song (IV)');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_rezept_h_gw4','Bowcraft 13. Makes Sala Mandra''s Last Song (IV).\n\nIntuition +3, Dexterity +2, Agility +1, Dodge +2, Bow +2; Immune to poison; Set (Moonwarden''s Raiment): AU +6 for each piece you own; all four: Dexterity +1, Intuition +1, Dodge +2 (re-equip after finding a piece)\nConsumes: 1 Moonwarden''s Oath (III), 1 Heavy Wyrm Scale, 1 Dragon sinew, 1 Gemstones.\nUNIQUE: the original cannot be bought again.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmMwHood_name','Perception +2');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmMwHood_short','Perception +2');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmMwHood_long','Perception +2');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_mw_hood','Moonwarden''s Hood');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_mw_hood','A grey-green hunter''s hood. Faelwen took it from a warden he sold. Part of the Moonwarden''s Raiment.\n\nIntuition +1, Perception +2');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmMwJerkin_name','AE +5');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmMwJerkin_short','AE +5');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmMwJerkin_long','AE +5');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_mw_jerkin','Moonwarden''s Jerkin');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_mw_jerkin','Elven leather that drinks moonlight. Its owner''s ghost still haunts the hollow tree where she died. Part of the Moonwarden''s Raiment.\n\nAgility +1, AE +5');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmMwBracers_name','Bow +1');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmMwBracers_short','Bow +1');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmMwBracers_long','Bow +1');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_mw_bracers','Moonwarden''s Bracers');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_mw_bracers','Iryan leather bracers stitched with silver leaves. Part of the Moonwarden''s Raiment.\n\nDexterity +1, Bow +1');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_mw_treads','Moonwarden''s Treads');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_mw_treads','Soft Iryan boots that leave no track. Part of the Moonwarden''s Raiment.\n\nAgility +1, Dodge +1');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmHTh1_name','AE +5, Arcane Lore +1');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmHTh1_short','AE +5, Arcane Lore +1');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmHTh1_long','AE +5, Arcane Lore +1');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_h_th1','Grimoire Locket (I)');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_h_th1','A locket holding one page of the grimoire you stole in Grangor. The rest of the book is out there, and it wants to be whole.\n\nAE +5, Arcane Lore +1');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmHTh2_name','Arcane Lore +2');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmHTh2_short','Arcane Lore +2');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmHTh2_long','Arcane Lore +2');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_h_th2','The Stolen Grimoire (II)');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_h_th2','The locket has grown into a tiny book on a chain. New pages appear at night, written in your own hand, about things you have not done yet.\n\nCleverness +1, AE +10, Arcane Lore +2\nSet (The Stolen Grimoire): AE +3 for each piece you own (re-equip after finding a piece)');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_rezept_h_th2','Plans: The Stolen Grimoire (II)');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_rezept_h_th2','Alchemy 8. Makes The Stolen Grimoire (II).\n\nCleverness +1, AE +10, Arcane Lore +2; Set (The Stolen Grimoire): AE +3 for each piece you own (re-equip after finding a piece)\nConsumes: 1 Grimoire Locket (I), 1 Crypt-louse Carapace, 1 Alcohol, 1 Gold leaf.\nUNIQUE: the original cannot be bought again.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmHTh3_name','Arcane Lore +3; Astral aura');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmHTh3_short','Arcane Lore +3; Astral aura');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmHTh3_long','Arcane Lore +3; Astral aura');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_h_th3','Grimoire of the Margins (III)');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_h_th3','Every margin is crowded with notes by every thief who ever owned it. Some of them are spells. One of them is a recipe for very good soup.\n\nCleverness +2, Intuition +1, AE +10, AE regeneration +1, Arcane Lore +3\nSet (The Stolen Grimoire): AE +4 for each piece you own; all four: Agility +1, Dodge +1 (re-equip after finding a piece)');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_rezept_h_th3','Plans: Grimoire of the Margins (III)');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_rezept_h_th3','Alchemy 11. Makes Grimoire of the Margins (III).\n\nCleverness +2, Intuition +1, AE +10, AE regeneration +1, Arcane Lore +3; Set (The Stolen Grimoire): AE +4 for each piece you own; all four: Agility +1, Dodge +1 (re-equip after finding a piece)\nConsumes: 1 The Stolen Grimoire (II), 1 Glittering Green Eye, 2 Gold leaf.\nUNIQUE: the original cannot be bought again.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmHTh4_name','AE +5; Astral aura');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmHTh4_short','AE +5; Astral aura');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmHTh4_long','AE +5; Astral aura');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_h_th4','The Unwritten Page (IV)');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_h_th4','Bound in a dragon scale, the grimoire is finally whole, and its last page is blank. It is waiting for you to write it.\n\nCleverness +2, Intuition +2, Agility +1, AE +15, AE regeneration +1, Magic resistance +2\nSet (The Stolen Grimoire): AE +3 for each piece you own; all four: Agility +1, Dodge +2, Attack +1 (re-equip after finding a piece)');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_rezept_h_th4','Plans: The Unwritten Page (IV)');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_rezept_h_th4','Alchemy 13. Makes The Unwritten Page (IV).\n\nCleverness +2, Intuition +2, Agility +1, AE +15, AE regeneration +1, Magic resistance +2; Set (The Stolen Grimoire): AE +3 for each piece you own; all four: Agility +1, Dodge +2, Attack +1 (re-equip after finding a piece)\nConsumes: 1 Grimoire of the Margins (III), 1 Heavy Wyrm Scale, 1 Dragon blood, 2 Gemstones.\nUNIQUE: the original cannot be bought again.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmGtCowl_name','AE +5');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmGtCowl_short','AE +5');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmGtCowl_long','AE +5');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_gt_cowl','Spellthief''s Cowl');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_gt_cowl','A wide hat with a hidden pocket for stolen spells. The necromancer of Tallon was wearing it. Part of the Stolen Grimoire.\n\nCleverness +1, AE +5');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmGtCoat_name','Magic resistance +2');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmGtCoat_short','Magic resistance +2');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmGtCoat_long','Magic resistance +2');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_gt_coat','Spellthief''s Coat');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_gt_coat','A dark leather coat lined with pages. Arrows hate it; so do spells. Part of the Stolen Grimoire.\n\nAgility +1, Magic resistance +2');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_gt_gloves','Ink-Stained Gloves');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_gt_gloves','Ravena''s gloves, stained with ink and older things. Part of the Stolen Grimoire.\n\nDexterity +2, Pick Pocket +2');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmGtBoots_name','Sneak +3');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmGtBoots_short','Sneak +3');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmGtBoots_long','Sneak +3');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_gt_boots','Margin-Walker Boots');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_gt_boots','High boots that walk where the map has no ink. Part of the Stolen Grimoire.\n\nAgility +1, Sneak +3');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_a_moonbow','Moonbow');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_a_moonbow','A pale elven bow. Its arrows find what the night hides.\n\nIntuition +1');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_s_thornwood','Thornwood Warbow');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_s_thornwood','A heavy war bow of black thornwood. Its arrows leave the wound open.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_s_silverleaf','Silverleaf Longbow');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_s_silverleaf','A longbow of silverleaf. Frost gathers on the string.\n\nDexterity +1');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmAMoonglove_name','Bow +2');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmAMoonglove_short','Bow +2');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmAMoonglove_long','Bow +2');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_a_moonglove','Archer''s Moon-Glove');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_a_moonglove','A soft elven shooting glove with a silver finger-guard.\n\nDexterity +1, Bow +2');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmMRfLionQueen_name','Golden aura');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmMRfLionQueen_short','Golden aura');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmMRfLionQueen_long','Golden aura');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_m_rf_lion_queen','Fang of the Lion Queen');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_m_rf_lion_queen','Rondra''s saber, reforged around a scale of the wyrm. Rhulana held it up to the forge-light and said only: ''Now Kurkum will sing of us.''\n\nCourage +2, Agility +1\nImmune to knockdown\n20% on hit: Sundered Guard\nAgainst downed foes: +1d6 damage\nAgainst burning foes: +1d6 fire damage\n10% on hit: wielder gains Lion''s Roar\n12% on hit: Wound');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_rezept_m_rf_lion_queen','Plans: Fang of the Lion Queen');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_rezept_m_rf_lion_queen','Smithing 13. Makes Fang of the Lion Queen.\n1D6+11 HP, AT +2, PA +1, INI +1\nCourage +2, Agility +1; Immune to knockdown; 20% on hit: Sundered Guard; Against downed foes: +1d6 damage; Against burning foes: +1d6 fire damage; 10% on hit: wielder gains Lion''s Roar; 12% on hit: Wound\nConsumes: 1 Fang of the Lioness, 1 Heavy Wyrm Scale, 2 Dwarven steel, 2 Gold leaf.\nUNIQUE: the original cannot be bought again.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmMRfRondraVerdict_name','Sabers +2; Golden aura');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmMRfRondraVerdict_short','Sabers +2; Golden aura');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmMRfRondraVerdict_long','Sabers +2; Golden aura');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_m_rf_rondra_verdict','Rondra''s Verdict');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_m_rf_rondra_verdict','Sabeth''s saber, purified and reforged. The outcast''s blade judges for Kurkum now, and it judges harshly.\n\nAgility +1, Courage +1, Sabers +2, Parry +1\n15% on hit: Sundered Guard\n12% on hit: Wound\nAgainst wounded foes: +1d6 damage\n10% on hit: wielder gains Lion''s Roar\nAgainst sundered foes: +1d6+2 damage');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_rezept_m_rf_rondra_verdict','Plans: Rondra''s Verdict');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_rezept_m_rf_rondra_verdict','Smithing 13. Makes Rondra''s Verdict.\n1D6+10 HP, AT +2, PA +1, INI +1\nAgility +1, Courage +1, Sabers +2, Parry +1; 15% on hit: Sundered Guard; 12% on hit: Wound; Against wounded foes: +1d6 damage; 10% on hit: wielder gains Lion''s Roar; Against sundered foes: +1d6+2 damage\nConsumes: 1 Lionsbane, 1 Heavy Wyrm Scale, 2 Dwarven steel, 2 Gold leaf.\nUNIQUE: the original cannot be bought again.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_m_rf_last_oath','Last Oath, Fulfilled');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_m_rf_last_oath','The dragonslayer hammer, finished at last with a scale of the dragon it was sworn against. The oath is kept; the hammer feels lighter for it.\n\nStrength +1, Constitution +1\nImmune to burning\n10% on hit: Knockdown\nAgainst downed foes: +1d6 damage\n12% on hit: Wound');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_rezept_m_rf_last_oath','Plans: Last Oath, Fulfilled');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_rezept_m_rf_last_oath','Smithing 13. Makes Last Oath, Fulfilled.\n1D6+9 HP, AT +1, PA -4, INI -1\nStrength +1, Constitution +1; Immune to burning; 10% on hit: Knockdown; Against downed foes: +1d6 damage; 12% on hit: Wound\nConsumes: 1 Last Oath of the Dragon-Slayer, 1 Heavy Wyrm Scale, 2 Dwarven steel, 1 Dragon blood.\nUNIQUE: the original cannot be bought again.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_m_rf_exile','Cleaver of the Returned Exile');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_m_rf_exile','Grimbart''s axe, reforged in the forges that once cast him out. Forgrimm brought it home, and the exile''s name is spoken in the halls again.\n\nStrength +2, Constitution +1, Courage +1\n15% on hit: Knockdown\n15% on hit: Frailty\nAgainst downed foes: +1d6+2 damage\n8% on hit: wielder gains Iron Skin\n12% on hit: Wound');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_rezept_m_rf_exile','Plans: Cleaver of the Returned Exile');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_rezept_m_rf_exile','Smithing 13. Makes Cleaver of the Returned Exile.\n2D6+7 HP, AT +1, INI -1\nStrength +2, Constitution +1, Courage +1; 15% on hit: Knockdown; 15% on hit: Frailty; Against downed foes: +1d6+2 damage; 8% on hit: wielder gains Iron Skin; 12% on hit: Wound\nConsumes: 1 Exile''s Cleaver, 1 Heavy Wyrm Scale, 2 Dwarven steel, 1 Dragon blood.\nUNIQUE: the original cannot be bought again.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmMRfSala_name','Falcon''s-eye aura');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmMRfSala_short','Falcon''s-eye aura');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmMRfSala_long','Falcon''s-eye aura');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_m_rf_sala','Sala Mandra''s Lullaby');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_m_rf_sala','The elven queen''s bow, restrung with dragon sinew. Its arrows sing their targets to sleep before the second note.\n\nIntuition +2, Agility +1');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_rezept_m_rf_sala','Plans: Sala Mandra''s Lullaby');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_rezept_m_rf_sala','Bowcraft 13. Makes Sala Mandra''s Lullaby.\n2D6+5 HP, AT +2\nIntuition +2, Agility +1\nConsumes: 1 Bow of Sala Mandra, 1 Heavy Wyrm Scale, 1 Dragon sinew, 1 Elf wood.\nUNIQUE: the original cannot be bought again.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmMRfDuskarrow_name','Falcon''s-eye aura');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmMRfDuskarrow_short','Falcon''s-eye aura');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmMRfDuskarrow_long','Falcon''s-eye aura');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_m_rf_duskarrow','Duskarrow Redeemed');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_m_rf_duskarrow','In Gwendala''s hands the grieving note is gone. She sang to it for a night and a day, the old songs of her people, and the bow learned them one by one: the song of the hunt that feeds the camp, the song of the watch at the forest''s edge, the song of the long way home. It will learn more. An elven bow has time.\n\nDexterity +1, Intuition +2');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_rezept_m_rf_duskarrow','Plans: Duskarrow Redeemed');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_rezept_m_rf_duskarrow','Bowcraft 13. Makes Duskarrow Redeemed.\n2D6+6 HP, AT +2, reload 2 CR\nDexterity +1, Intuition +2\nConsumes: 1 Duskarrow, 1 Heavy Wyrm Scale, 1 Dragon sinew, 1 Elf wood.\nUNIQUE: the original cannot be bought again.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmMRfCrimson_name','Silver aura');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmMRfCrimson_short','Silver aura');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmMRfCrimson_long','Silver aura');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_m_rf_crimson','Crimson Vow, Unbroken');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_m_rf_crimson','Ravena''s dirk, reforged around a wyrm scale. The Circle''s oath is yours alone now, and the blade knows it.\n\nAgility +2, Dexterity +1, AE +10, Cleverness +1\n20% on hit: Bleeding\n15% on hit: Starburn\nAgainst bleeding foes: +1d6+2 damage\nOn hit: restores 1 AE to the wielder\n10% on hit: wielder gains Shadowstep\n10% on hit: wielder gains Astral Surge');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_rezept_m_rf_crimson','Plans: Crimson Vow, Unbroken');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_rezept_m_rf_crimson','Smithing 13. Makes Crimson Vow, Unbroken.\n1D6+9 HP, AT +2, INI +2\nAgility +2, Dexterity +1, AE +10, Cleverness +1; 20% on hit: Bleeding; 15% on hit: Starburn; Against bleeding foes: +1d6+2 damage; On hit: restores 1 AE to the wielder; 10% on hit: wielder gains Shadowstep; 10% on hit: wielder gains Astral Surge\nConsumes: 1 Crimson Vow, 1 Heavy Wyrm Scale, 1 Dwarven steel, 2 Gemstones.\nUNIQUE: the original cannot be bought again.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmMRfPhex_name','Silver aura');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmMRfPhex_short','Silver aura');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmMRfPhex_long','Silver aura');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_m_rf_phex','Phex''s Final Jest');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_m_rf_phex','The dragon-tooth dagger, stolen from the wyrm twice and finally fitted with a piece of the wyrm itself. Phex is delighted. The wyrm, less so.\n\nPick Pocket +2, Agility +1, Dexterity +2\n20% on hit: Dazed\n15% on hit: Wyrm Venom\nAgainst dazed foes: +1d6 damage\n10% on hit: wielder gains Quickstep\n15% on hit: Shadowstep\n10% on hit: Wound');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_rezept_m_rf_phex','Plans: Phex''s Final Jest');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_rezept_m_rf_phex','Smithing 13. Makes Phex''s Final Jest.\n1D6+8 HP, AT +2, INI +2\nPick Pocket +2, Agility +1, Dexterity +2; 20% on hit: Dazed; 15% on hit: Wyrm Venom; Against dazed foes: +1d6 damage; 10% on hit: wielder gains Quickstep; 15% on hit: Shadowstep; 10% on hit: Wound\nConsumes: 1 Phex''s Last Laugh, 1 Heavy Wyrm Scale, 1 Dwarven steel, 2 Gemstones.\nUNIQUE: the original cannot be bought again.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_m_rk_robe','Rakorium''s Robe of Disputation');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_m_rk_robe','Rakorium won every academic argument in this robe, mostly by talking until the other side left. It is warm, and smells of ink.\n\nAE +10, Magic resistance +2, Cleverness +1');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmLqPauldrons_name','LE +5');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmLqPauldrons_short','LE +5');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmLqPauldrons_long','LE +5');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_lq_pauldrons','Lioness Pauldrons');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_lq_pauldrons','Gilded shoulder plates with lion heads. Sabeth wore them over the stolen cuirass.\n\nCourage +1, LE +5');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmMwMantle_name','Perception +2');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmMwMantle_short','Perception +2');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmMwMantle_long','Perception +2');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_mw_mantle','Moonwarden''s Mantle');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_mw_mantle','A short grey-green shoulder cape of Iryan leather. It whispers when an arrow is about to be loosed.\n\nIntuition +1, Perception +2');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmAPatchMantle_name','Sneak +2, AE +5');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmAPatchMantle_short','Sneak +2, AE +5');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmAPatchMantle_long','Sneak +2, AE +5');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_a_patch_mantle','Thief''s Patch-Mantle');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_a_patch_mantle','Stitched from a dozen stolen cloaks. Each patch remembers a different alley.\n\nSneak +2, AE +5');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_r_splitting_maul','Holdwin''s Splitting Maul');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_r_splitting_maul','The woodcutter swore by it for thirty years. Logs, bandits, the occasional stubborn bear.\n\n8% on hit: Knockdown');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmWpMantle_name','Magic resistance +1');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmWpMantle_short','Magic resistance +1');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmWpMantle_long','Magic resistance +1');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_wp_mantle','White Fur Mantle');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_wp_mantle','Iryan leather shoulders lined with the silver ruff of White Fur, the pale wolf-mother of the Avestrue woods. Other wolves smell their old leader on you and hesitate.\n\nMagic resistance +1');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_rezept_wp_mantle','Plans: White Fur Mantle');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_rezept_wp_mantle','Bowcraft 4. Makes White Fur Mantle.\nChest 1, Back 1, Arms 1; leather, encumbrance 0.1\nMagic resistance +1\nConsumes: 1 Silver Ruff of White Fur, 2 Wolfskin, 2 Leather strips.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmWpJerkin_name','Sneak +2, AU +5');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmWpJerkin_short','Sneak +2, AU +5');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmWpJerkin_long','Sneak +2, AU +5');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_wp_jerkin','Darkwolf Jerkin');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_wp_jerkin','Iryan leather faced with dark wolf pelt, cut to the pattern of Grimmzahn''s last ranger. Light enough to run in, quiet enough to hunt in.\n\nSneak +2, AU +5\nSet (The Wolfpack): AU +2 for each piece you own; all four: Dodge +1, Sneak +2 (re-equip after finding a piece)');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_rezept_wp_jerkin','Plans: Darkwolf Jerkin');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_rezept_wp_jerkin','Bowcraft 8. Makes Darkwolf Jerkin.\nChest 3, Belly 3, Back 3, Arms 1; leather, encumbrance 1.1\nSneak +2, AU +5; Set (The Wolfpack): AU +2 for each piece you own; all four: Dodge +1, Sneak +2 (re-equip after finding a piece)\nConsumes: 3 Dark Wolf Pelt, 2 Leather strips, 1 Improved sinews.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmWpBreeches_name','Perception +2');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmWpBreeches_short','Perception +2');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmWpBreeches_long','Perception +2');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_wp_breeches','Darkwolf Breeches');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_wp_breeches','Heavy-duty leather trousers reworked with dark pelt at the knees and belt. They no longer creak, and they remember every trail.\n\nPerception +2');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_rezept_wp_breeches','Plans: Darkwolf Breeches');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_rezept_wp_breeches','Bowcraft 7. Makes Darkwolf Breeches.\nBelly 1, Legs 2; leather, encumbrance 0.0\nPerception +2\nConsumes: 1 Heavy-duty Leather Pants, 2 Dark Wolf Pelt, 1 Leather strips.\nThe source item can be bought again.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmWpGrips_name','Bow +1');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmWpGrips_short','Bow +1');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmWpGrips_long','Bow +1');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_wp_grips','Darkwolf Grips');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_wp_grips','Iryan leather gloves with a wolf fang set over each knuckle. A steady bow hand, and an unpleasant surprise for anyone who grabs it.\n\nBow +1');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_rezept_wp_grips','Plans: Darkwolf Grips');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_rezept_wp_grips','Bowcraft 6. Makes Darkwolf Grips.\nArms 2; leather, encumbrance 0.2\nBow +1\nConsumes: 1 Dark Wolf Pelt, 2 Wolf Fang, 1 Leather strips.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmMhMantle_name','Sneak +2, Magic resistance +1');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmMhMantle_short','Sneak +2, Magic resistance +1');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmMhMantle_long','Sneak +2, Magic resistance +1');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_mh_mantle','Moonhowl Mantle');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_mh_mantle','A wolf-fur mantle relined with moon-mad pelt. Its silver hairs stand up whenever a spell is cast nearby, and something in the fur turns the spell aside.\n\nSneak +2, Magic resistance +1');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_rezept_mh_mantle','Plans: Moonhowl Mantle');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_rezept_mh_mantle','Bowcraft 8. Makes Moonhowl Mantle.\nChest 1, Back 1, Arms 1; leather, encumbrance 0.2\nSneak +2, Magic resistance +1\nConsumes: 1 White Fur Mantle, 2 Moon-mad Pelt, 1 Moon-mad Sinew, 2 Leather strips.\nThe source item can be bought again.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmMhJerkin_name','Sneak +3');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmMhJerkin_short','Sneak +3');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmMhJerkin_long','Sneak +3');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_mh_jerkin','Moonhowl Jerkin');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_mh_jerkin','A darkwolf jerkin rebuilt around the mane of Greymaw, the mad alpha. Light as ever, and nothing in the woods hears you coming.\n\nSneak +3, AU +10, Agility +1\nSet (The Moonhowl Pack): AU +3 for each piece you own; all four: Dodge +1, Sneak +3, Magic resistance +1 (re-equip after finding a piece)');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_rezept_mh_jerkin','Plans: Moonhowl Jerkin');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_rezept_mh_jerkin','Bowcraft 11. Makes Moonhowl Jerkin.\nChest 4, Belly 4, Back 4, Arms 1; leather, encumbrance 1.4\nSneak +3, AU +10, Agility +1; Set (The Moonhowl Pack): AU +3 for each piece you own; all four: Dodge +1, Sneak +3, Magic resistance +1 (re-equip after finding a piece)\nConsumes: 1 Darkwolf Jerkin, 1 Greymaw''s Mane, 2 Moon-mad Pelt, 1 Moon-mad Sinew.\nThe source item can be bought again.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmMhBreeches_name','Perception +3, AU +5');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmMhBreeches_short','Perception +3, AU +5');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmMhBreeches_long','Perception +3, AU +5');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_mh_breeches','Moonhowl Breeches');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_mh_breeches','Darkwolf breeches with moon-mad pelt sewn over the thighs. You hear the twig before you step on it.\n\nPerception +3, AU +5');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_rezept_mh_breeches','Plans: Moonhowl Breeches');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_rezept_mh_breeches','Bowcraft 9. Makes Moonhowl Breeches.\nBelly 1, Legs 3; leather, encumbrance 0.0\nPerception +3, AU +5\nConsumes: 1 Darkwolf Breeches, 2 Moon-mad Pelt, 1 Leather strips.\nThe source item can be bought again.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmMhGrips_name','Bow +2');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmMhGrips_short','Bow +2');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmMhGrips_long','Bow +2');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_mh_grips','Moonhowl Grips');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_mh_grips','Darkwolf gloves re-stitched with humming moon-sinew. The bow hand never shakes, not even when it should.\n\nBow +2, Dexterity +1');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_rezept_mh_grips','Plans: Moonhowl Grips');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_rezept_mh_grips','Bowcraft 9. Makes Moonhowl Grips.\nArms 2; leather, encumbrance 0.2\nBow +2, Dexterity +1\nConsumes: 1 Darkwolf Grips, 1 Moon-mad Pelt, 2 Moon-mad Sinew.\nThe source item can be bought again.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_mh_bow','Moonhowl Longbow');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_mh_bow','A longbow strung with sinew from the moon-mad pack. When it looses, the string howls, and sometimes the sky answers.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_rezept_mh_bow','Plans: Moonhowl Longbow');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_rezept_mh_bow','Bowcraft 10. Makes Moonhowl Longbow.\n3D6+3 HP, AT +1, reload 2 CR\nConsumes: 1 Longbow, 3 Moon-mad Sinew, 1 Elf wood.\nThe source item can be bought again.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmMhIryanShoulders_name','Magic resistance +2, Perception +2');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmMhIryanShoulders_short','Magic resistance +2, Perception +2');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmMhIryanShoulders_long','Magic resistance +2, Perception +2');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_mh_iryan_shoulders','Stormhowl Shoulder Guards');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_mh_iryan_shoulders','Iryan shoulder guards with Stormhowl''s heartstone sewn under the left plate. The wearer moves a heartbeat ahead of every blow, and spells slide off.\n\nMagic resistance +2, Dodge +1, Perception +2');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_rezept_mh_iryan_shoulders','Plans: Stormhowl Shoulder Guards');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_rezept_mh_iryan_shoulders','Bowcraft 10. Makes Stormhowl Shoulder Guards.\nChest 2, Back 2, Arms 3; leather, encumbrance 0.3\nMagic resistance +2, Dodge +1, Perception +2\nConsumes: 1 Iryan Leather Shoulder Guards, 1 Stormhowl''s Heartstone, 2 Moon-mad Pelt, 2 Leather strips.\nUNIQUE: the original cannot be bought again.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmTcCuirass_name','LE +5, Willpower +1');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmTcCuirass_short','LE +5, Willpower +1');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmTcCuirass_long','LE +5, Willpower +1');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_tc_cuirass','Tuskhide Cuirass');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_tc_cuirass','Ferdok''s drovers wear tusk-plated leather when they drive the herds past the boar woods. A Count''s Town smith made the idea fit for a fight. It creaks, it smells of the field, and it turns a blade.\n\nLE +5, Willpower +1\nSet (Tuskhide): LE +2 for each piece you own; all four: Willpower +2, AU +5 (re-equip after finding a piece)');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_rezept_tc_cuirass','Plans: Tuskhide Cuirass');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_rezept_tc_cuirass','Smithing 5. Makes Tuskhide Cuirass.\nChest 4, Belly 3, Back 3, Arms 1; leather, encumbrance 2.0\nLE +5, Willpower +1; Set (Tuskhide): LE +2 for each piece you own; all four: Willpower +2, AU +5 (re-equip after finding a piece)\nConsumes: 1 Leather Cuirass, 4 Boar Tusk, 2 Leather strips.\nThe source item can be bought again.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmTcBracers_name','AU +5');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmTcBracers_short','AU +5');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmTcBracers_long','AU +5');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_tc_bracers','Tuskhide Bracers');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_tc_bracers','Studded arm guards with a row of tusk tips down each forearm, a drover''s trick for keeping angry bulls at arm''s length.\n\nAU +5');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_rezept_tc_bracers','Plans: Tuskhide Bracers');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_rezept_tc_bracers','Smithing 4. Makes Tuskhide Bracers.\nArms 2; leather, encumbrance 0.2\nAU +5\nConsumes: 1 Studded Arm Greaves, 2 Boar Tusk, 1 Leather strips.\nThe source item can be bought again.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmTcHelm_name','LE +5, AU +5');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmTcHelm_short','LE +5, AU +5');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmTcHelm_long','LE +5, AU +5');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_tc_helm','Bearclaw Helm');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_tc_helm','A leather helm with bear claws sewn round the brow, in the old fashion of the Avestrue hunters. It does not make you braver; it makes you harder to kill while you find out.\n\nLE +5, AU +5');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_rezept_tc_helm','Plans: Bearclaw Helm');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_rezept_tc_helm','Bowcraft 5. Makes Bearclaw Helm.\nHead 3; leather, encumbrance 0.6\nLE +5, AU +5\nConsumes: 1 Leather Helm, 2 Bear Claw, 1 Leather strips.\nThe source item can be bought again.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmTsCuirass_name','LE +8, Willpower +2, Magic resistance +1');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmTsCuirass_short','LE +8, Willpower +2, Magic resistance +1');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmTsCuirass_long','LE +8, Willpower +2, Magic resistance +1');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_ts_cuirass','Ironshell Cuirass');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_ts_cuirass','A tusk cuirass faced with giant-crab shell from the Ferdok harbour. Blades skid off it the way oars skid off a hull.\n\nLE +8, Willpower +2, Magic resistance +1\nSet (Ironshell): LE +3 for each piece you own; all four: Parry +1, Magic resistance +1 (re-equip after finding a piece)');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_rezept_ts_cuirass','Plans: Ironshell Cuirass');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_rezept_ts_cuirass','Smithing 8. Makes Ironshell Cuirass.\nChest 5, Belly 4, Back 5, Arms 1; leather, encumbrance 2.0\nLE +8, Willpower +2, Magic resistance +1; Set (Ironshell): LE +3 for each piece you own; all four: Parry +1, Magic resistance +1 (re-equip after finding a piece)\nConsumes: 1 Tuskhide Cuirass, 3 Crab Shell Plate, 1 Steel.\nThe source item can be bought again.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmTsBracers_name','AU +5');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmTsBracers_short','AU +5');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmTsBracers_long','AU +5');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_ts_bracers','Ironshell Bracers');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_ts_bracers','Tusk bracers plated with crab shell at the wrist. They ring like a bell when struck, and the ringing puts duellists off their stroke.\n\nAU +5, Parry +1');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_rezept_ts_bracers','Plans: Ironshell Bracers');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_rezept_ts_bracers','Smithing 7. Makes Ironshell Bracers.\nArms 3; leather, encumbrance 0.2\nAU +5, Parry +1\nConsumes: 1 Tuskhide Bracers, 2 Crab Shell Plate.\nThe source item can be bought again.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmTsHelm_name','Intimidate +3, Magic resistance +1');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmTsHelm_short','Intimidate +3, Magic resistance +1');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmTsHelm_long','Intimidate +3, Magic resistance +1');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_ts_helm','Ironshell Helm');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_ts_helm','A clawed helm lined with bitter troll-toad leather and capped with crab shell. Curses taste it and decide to look for someone else.\n\nIntimidate +3, Magic resistance +1');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_rezept_ts_helm','Plans: Ironshell Helm');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_rezept_ts_helm','Smithing 7. Makes Ironshell Helm.\nHead 5; leather, encumbrance 0.6\nIntimidate +3, Magic resistance +1\nConsumes: 1 Bearclaw Helm, 2 Crab Shell Plate, 1 Troll-toad Wart.\nThe source item can be bought again.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmTwCuirass_name','LE +2');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmTwCuirass_short','LE +2');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmTwCuirass_long','LE +2');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_tw_cuirass','Warlord Cuirass');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_tw_cuirass','Crab shell and tusk over the hide of the Tallon ogre-chief, bound with Kosh steel and a linnorm fang over the heart. Its wearer does not fall down. Things fall down around its wearer.\n\nLE +12, Courage +1, Strength +1\nImmune to knockdown\nSet (The Warlord): LE +4 for each piece you own; all four: Attack +1, Parry +1 (re-equip after finding a piece)');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_rezept_tw_cuirass','Plans: Warlord Cuirass');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_rezept_tw_cuirass','Smithing 11. Makes Warlord Cuirass.\nChest 5, Belly 5, Back 6, Arms 2; leather, encumbrance 2.0\nLE +12, Courage +1, Strength +1; Immune to knockdown; Set (The Warlord): LE +4 for each piece you own; all four: Attack +1, Parry +1 (re-equip after finding a piece)\nConsumes: 1 Ironshell Cuirass, 1 Ogre Chief''s Hide, 1 Tatzelwurm Fang, 1 Kosh steel.\nThe source item can be bought again.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmTwBracers_name','AU +5');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmTwBracers_short','AU +5');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmTwBracers_long','AU +5');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_tw_bracers','Warlord Bracers');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_tw_bracers','Shell bracers reforged around the heartstone of a stone guardian. They still remember how to hold a line that must not break.\n\nAttack +1, Dexterity +1, AU +5');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_rezept_tw_bracers','Plans: Warlord Bracers');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_rezept_tw_bracers','Smithing 10. Makes Warlord Bracers.\nArms 5; leather, encumbrance 0.3\nAttack +1, Dexterity +1, AU +5\nConsumes: 1 Ironshell Bracers, 1 Golem Heartstone, 2 Crypt-louse Carapace, 1 Dwarven steel.\nThe source item can be bought again.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmTwHelm_name','Intimidate +3, Magic resistance +1');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmTwHelm_short','Intimidate +3, Magic resistance +1');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmTwHelm_long','Intimidate +3, Magic resistance +1');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_tw_helm','Warlord Helm');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_tw_helm','A shell helm under a crest of dwarven steel. Its wearer is always the one the others look to, which is not always a comfort.\n\nCourage +1, Intimidate +3, Magic resistance +1');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_rezept_tw_helm','Plans: Warlord Helm');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_rezept_tw_helm','Smithing 10. Makes Warlord Helm.\nHead 6; leather, encumbrance 0.6\nCourage +1, Intimidate +3, Magic resistance +1\nConsumes: 1 Ironshell Helm, 2 Bear Claw, 1 Dwarven steel.\nThe source item can be bought again.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmWwRobe_name','Magic resistance +1');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmWwRobe_short','Magic resistance +1');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmWwRobe_long','Magic resistance +1');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_ww_robe','Witchweave Robe');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_ww_robe','The forest witches spin spider silk with toad sap until the thread stops tangling. Saphira says a robe like this listens to its wearer. She will not say what it answers.\n\nAE +10, Magic resistance +1\nSet (Witchweave): AE +2 for each piece you own; all four: Magic resistance +1, Intuition +1 (re-equip after finding a piece)');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_rezept_ww_robe','Plans: Witchweave Robe');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_rezept_ww_robe','Alchemy 6. Makes Witchweave Robe.\nChest 2, Belly 2, Back 2, Arms 1; cloth, encumbrance 0.0\nAE +10, Magic resistance +1; Set (Witchweave): AE +2 for each piece you own; all four: Magic resistance +1, Intuition +1 (re-equip after finding a piece)\nConsumes: 1 Green Magician''s Robe, 2 Silk gland, 2 Troll-toad Wart.\nThe source item can be bought again.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmWwHood_name','AE +5, Arcane Lore +2');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmWwHood_short','AE +5, Arcane Lore +2');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmWwHood_long','AE +5, Arcane Lore +2');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_ww_hood','Witchweave Hat');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_ww_hood','A pointed hat stiffened with spider silk in the witches'' way. Whatever it hears, it whispers to you, mostly gossip.\n\nAE +5, Arcane Lore +2');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_rezept_ww_hood','Plans: Witchweave Hat');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_rezept_ww_hood','Alchemy 5. Makes Witchweave Hat.\nHead 2; cloth, encumbrance 0.0\nAE +5, Arcane Lore +2\nConsumes: 1 Pointy Hat, 1 Silk gland, 1 Troll-toad Wart.\nThe source item can be bought again.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmWwShoes_name','AE +3, Sneak +2');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmWwShoes_short','AE +3, Sneak +2');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmWwShoes_long','AE +3, Sneak +2');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_ww_shoes','Witchweave Slippers');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_ww_shoes','Soft shoes soled with silk and a warm firefly sac in each heel. The witches wear them to dance in the woods without leaving a trace.\n\nAE +3, Sneak +2');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_rezept_ww_shoes','Plans: Witchweave Slippers');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_rezept_ww_shoes','Alchemy 5. Makes Witchweave Slippers.\nLegs 1; leather, encumbrance 0.0\nAE +3, Sneak +2\nConsumes: 1 Magician''s Shoes, 1 Silk gland, 1 Firefly Ember Sac.\nThe source item can be bought again.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmWeRobe_name','AE +5');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmWeRobe_short','AE +5');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmWeRobe_long','AE +5');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_we_robe','Emberweave Robe');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_we_robe','A witch-robe threaded with glowing firefly silk and a glittering green eye at the collar. Tallon''s magician helped with the stitching, and the robe will not burn.\n\nAE +15, Magic resistance +2\nImmune to burning\nSet (Emberweave): AE +3 for each piece you own; all four: Magic resistance +2, Cleverness +1 (re-equip after finding a piece)');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_rezept_we_robe','Plans: Emberweave Robe');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_rezept_we_robe','Alchemy 10. Makes Emberweave Robe.\nChest 3, Belly 3, Back 3, Arms 1; cloth, encumbrance 0.0\nAE +15, Magic resistance +2; Immune to burning; Set (Emberweave): AE +3 for each piece you own; all four: Magic resistance +2, Cleverness +1 (re-equip after finding a piece)\nConsumes: 1 Witchweave Robe, 2 Firefly Ember Sac, 1 Glittering Green Eye.\nThe source item can be bought again.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmWeHood_name','AE +8, Arcane Lore +3');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmWeHood_short','AE +8, Arcane Lore +3');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmWeHood_long','AE +8, Arcane Lore +3');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_we_hood','Emberweave Hat');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_we_hood','A witch''s hat with a glittering green eye set over the brim. It sees spells coming a moment before you do.\n\nAE +8, Arcane Lore +3, Intuition +1');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_rezept_we_hood','Plans: Emberweave Hat');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_rezept_we_hood','Alchemy 9. Makes Emberweave Hat.\nHead 2; cloth, encumbrance 0.0\nAE +8, Arcane Lore +3, Intuition +1\nConsumes: 1 Witchweave Hat, 1 Glittering Green Eye, 1 Firefly Ember Sac.\nThe source item can be bought again.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmWeShoes_name','AE +5, Sneak +2');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmWeShoes_short','AE +5, Sneak +2');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmWeShoes_long','AE +5, Sneak +2');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_we_shoes','Emberweave Slippers');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_we_shoes','Witch slippers with ember-sac soles that never cool. Light steps, warm feet, quick hands: the old Tallon recipe for a long night.\n\nAE +5, Sneak +2, Agility +1');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_rezept_we_shoes','Plans: Emberweave Slippers');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_rezept_we_shoes','Alchemy 9. Makes Emberweave Slippers.\nLegs 1; leather, encumbrance 0.0\nAE +5, Sneak +2, Agility +1\nConsumes: 1 Witchweave Slippers, 2 Firefly Ember Sac.\nThe source item can be bought again.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmShMantle_name','Sneak +3, Perception +2');
