INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmShMantle_long','Sneak +3, Perception +2');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_sh_mantle','Skyhunter Mantle');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_sh_mantle','A moonhowl mantle fringed with harpy feathers from the Tallon cliffs. It catches the wind, and arrows that should hit you catch nothing.\n\nSneak +3, Perception +2, Dodge +1');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_rezept_sh_mantle','Plans: Skyhunter Mantle');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_rezept_sh_mantle','Bowcraft 11. Makes Skyhunter Mantle.\nChest 1, Back 1, Arms 2; leather, encumbrance 0.2\nSneak +3, Perception +2, Dodge +1\nConsumes: 1 Moonhowl Mantle, 3 Harpy feathers, 1 Improved sinews.\nThe source item can be bought again.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmShGrips_name','Bow +3');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmShGrips_short','Bow +3');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmShGrips_long','Bow +3');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_sh_grips','Skyhunter Grips');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_sh_grips','Moonhowl gloves with a bear claw over the draw finger and harpy down in the palm. The string leaves the hand as softly as a sigh.\n\nBow +3, Dexterity +1');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_rezept_sh_grips','Plans: Skyhunter Grips');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_rezept_sh_grips','Bowcraft 11. Makes Skyhunter Grips.\nArms 2; leather, encumbrance 0.2\nBow +3, Dexterity +1\nConsumes: 1 Moonhowl Grips, 2 Harpy feathers, 1 Bear Claw.\nThe source item can be bought again.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmShHood_name','Perception +3, Bow +1');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmShHood_short','Perception +3, Bow +1');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmShHood_long','Perception +3, Bow +1');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_sh_hood','Skyhunter Hood');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_sh_hood','A leather hood crested with harpy feathers. You see the hawk before the hawk sees you.\n\nPerception +3, Bow +1');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_rezept_sh_hood','Plans: Skyhunter Hood');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_rezept_sh_hood','Bowcraft 9. Makes Skyhunter Hood.\nHead 2; leather, encumbrance 0.2\nPerception +3, Bow +1\nConsumes: 1 Leather Cap, 3 Harpy feathers, 1 Leather strips.\nThe source item can be bought again.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmWfMantle2_name','AU +5, Magic resistance +2');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmWfMantle2_short','AU +5, Magic resistance +2');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmWfMantle2_long','AU +5, Magic resistance +2');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_wf_mantle2','Silverpelt Mantle');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_wf_mantle2','The White Fur mantle, relined with the pelt of Duskmane, old lord of the Rattelshof pack. It is warmer now, and heavier with two wolves'' worth of pride.\n\nAU +5, Magic resistance +2');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_rezept_wf_mantle2','Plans: Silverpelt Mantle');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_rezept_wf_mantle2','Bowcraft 9. Makes Silverpelt Mantle.\nChest 1, Back 1, Arms 1; leather, encumbrance 0.2\nAU +5, Magic resistance +2\nConsumes: 1 White Fur Mantle, 1 Pelt of Duskmane, 2 Leather strips.\nThe source item can be bought again.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmWfMantle3_name','Magic resistance +2');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmWfMantle3_short','Magic resistance +2');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmWfMantle3_long','Magic resistance +2');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_wf_mantle3','Mantle of the Pack-Mother');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_wf_mantle3','Three wolves'' furs bound with Aldessia''s silver tincture and the mane of the mad alpha. Wolves bow their heads to whoever wears it, and men find they would rather not try.\n\nAU +10, Magic resistance +2, Courage +1');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_rezept_wf_mantle3','Plans: Mantle of the Pack-Mother');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_rezept_wf_mantle3','Bowcraft 12. Makes Mantle of the Pack-Mother.\nChest 1, Back 1, Arms 2; leather, encumbrance 0.2\nAU +10, Magic resistance +2, Courage +1\nConsumes: 1 Silverpelt Mantle, 1 Greymaw''s Mane, 1 Aldessia''s Silver Tincture, 2 Leather strips.\nThe source item can be bought again.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmRlSunwardHelm_name','Magic resistance +2, LE +5, AU +5');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmRlSunwardHelm_short','Magic resistance +2, LE +5, AU +5');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmRlSunwardHelm_long','Magic resistance +2, LE +5, AU +5');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_rl_sunward_helm','Sunward Helm');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_rl_sunward_helm','A clawed helm crowned with the Grand Inquisitor''s own seal. Magic slides off it the way his sermons slid off the witches of the Dark Forest.\n\nMagic resistance +2, LE +5, AU +5');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_rezept_rl_sunward_helm','Plans: Sunward Helm');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_rezept_rl_sunward_helm','Smithing 8. Makes Sunward Helm.\nHead 4; leather, encumbrance 0.6\nMagic resistance +2, LE +5, AU +5\nConsumes: 1 Bearclaw Helm, 1 Inquisitor''s Sun-Seal, 1 Gold leaf.\nThe source item can be bought again.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmRlCinderWard_name','AU +5');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmRlCinderWard_short','AU +5');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmRlCinderWard_long','AU +5');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_rl_cinder_ward','Cinder Ward');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_rl_cinder_ward','A pinch of the dragon-cult''s sacred cinder sealed in a gold locket. The fire that answered their prayers does not answer anyone''s against you.\n\nAU +5\nImmune to burning');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_rezept_rl_cinder_ward','Plans: Cinder Ward');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_rezept_rl_cinder_ward','Bowcraft 7. Makes Cinder Ward.\n\nAU +5; Immune to burning\nConsumes: 1 Cinder of the Dragon-Cult, 1 Leather strips.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_tg_stiletto','Guild Stiletto');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_tg_stiletto','A narrow guild blade with a cord-wrapped grip. It goes in between the rings of a mail shirt.\n\n12% on hit: Bleeding');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmTgBuckler_name','Pick Pocket +1');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmTgBuckler_short','Pick Pocket +1');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmTgBuckler_long','Pick Pocket +1');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_tg_buckler','Cutpurse''s Buckler');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_tg_buckler','A fist-sized buckler with a hidden pocket behind the boss.\n\nDodge +1, Pick Pocket +1');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_tg_stars','Guild Throwing Stars');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_tg_stars','Blackened steel stars, balanced to fly flat and quiet.\n\n15% on hit: Dazed');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmTgHalfboots_name','Sneak +2, Pick Pocket +1');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmTgHalfboots_short','Sneak +2, Pick Pocket +1');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmTgHalfboots_long','Sneak +2, Pick Pocket +1');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_tg_halfboots','Cutpurse''s Half-Boots');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_tg_halfboots','Soft half-boots with felt soles. Cobbles, floorboards and gravel all keep quiet.\n\nSneak +2, Pick Pocket +1');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_rezept_tg_halfboots','Plans: Cutpurse''s Half-Boots');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_rezept_tg_halfboots','Bowcraft 5. Makes Cutpurse''s Half-Boots.\nLegs 2; leather, encumbrance 0.0\nSneak +2, Pick Pocket +1\nConsumes: 1 Half-Boot, 2 Leather strips.\nThe source item can be bought again.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmTgGloves1_name','Pick Locks +1');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmTgGloves1_short','Pick Locks +1');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmTgGloves1_long','Pick Locks +1');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_tg_gloves1','Night Hand Gloves');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_tg_gloves1','The Gloves of Shadow, relined with wolf-fang grips by the guild. Locks and purses open for them.\n\nDexterity +3, Pick Pocket +2, Pick Locks +1');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_rezept_tg_gloves1','Plans: Night Hand Gloves');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_rezept_tg_gloves1','Bowcraft 6. Makes Night Hand Gloves.\nArms 2; leather, encumbrance 0.0\nDexterity +3, Pick Pocket +2, Pick Locks +1\nConsumes: 1 Gloves of Shadow, 2 Leather strips, 1 Wolf Fang.\nThe source item can be bought again.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmTgPhexCoin_name','Pick Locks +2, Disarm Traps +2, Haggle +1');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmTgPhexCoin_short','Pick Locks +2, Disarm Traps +2, Haggle +1');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmTgPhexCoin_long','Pick Locks +2, Disarm Traps +2, Haggle +1');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_tg_phex_coin','Phex''s Lucky Coin');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_tg_phex_coin','A worn coin with the fox of Phex on both sides. It always lands the right way up.\n\nPick Locks +2, Disarm Traps +2, Haggle +1');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmTgNrVeil_name','Sneak +2, Perception +2');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmTgNrVeil_short','Sneak +2, Perception +2');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmTgNrVeil_long','Sneak +2, Perception +2');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_tg_nr_veil','Nightrunner Veil');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_tg_nr_veil','A black silk veil from the Iryan workshops. You see everything; nobody sees your face.\n\nSneak +2, Perception +2');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_rezept_tg_nr_veil','Plans: Nightrunner Veil');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_rezept_tg_nr_veil','Bowcraft 7. Makes Nightrunner Veil.\nHead 2; cloth, encumbrance 0.0\nSneak +2, Perception +2\nConsumes: 1 Silk Keffiyeh, 1 Leather strips, 1 Gemstones.\nThe source item can be bought again.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmTgNrJerkin_name','Sneak +2');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmTgNrJerkin_short','Sneak +2');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmTgNrJerkin_long','Sneak +2');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_tg_nr_jerkin','Nightrunner Jerkin');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_tg_nr_jerkin','Black Iryan leather, cut close and oiled silent. No buckle catches the light.\n\nSneak +2, Dodge +1');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_rezept_tg_nr_jerkin','Plans: Nightrunner Jerkin');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_rezept_tg_nr_jerkin','Bowcraft 8. Makes Nightrunner Jerkin.\nChest 4, Belly 4, Back 3, Arms 1; leather, encumbrance 1.3\nSneak +2, Dodge +1\nConsumes: 1 Iryan Armor, 3 Leather strips, 1 Glittering Green Eye.\nThe source item can be bought again.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmTgNrBoots_name','Sneak +2');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmTgNrBoots_short','Sneak +2');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmTgNrBoots_long','Sneak +2');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_tg_nr_boots','Nightrunner Boots');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_tg_nr_boots','Iryan boots with split soles. Roof tiles are no harder than a road.\n\nSneak +2, Dodge +1');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_rezept_tg_nr_boots','Plans: Nightrunner Boots');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_rezept_tg_nr_boots','Bowcraft 7. Makes Nightrunner Boots.\nLegs 3; leather, encumbrance 0.2\nSneak +2, Dodge +1\nConsumes: 1 Iryan Leather Shoes, 2 Leather strips.\nThe source item can be bought again.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmTgGloves2_name','Pick Pocket +1, Pick Locks +2');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmTgGloves2_short','Pick Pocket +1, Pick Locks +2');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmTgGloves2_long','Pick Pocket +1, Pick Locks +2');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_tg_gloves2','Velvet Hand Gloves');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_tg_gloves2','The Night Hand, with a green spider-eye stitched into each palm. The fingers find the gap before the eye does.\n\nDexterity +3, Attack +1, Pick Pocket +3, Pick Locks +2');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_rezept_tg_gloves2','Plans: Velvet Hand Gloves');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_rezept_tg_gloves2','Bowcraft 9. Makes Velvet Hand Gloves.\nArms 3; leather, encumbrance 0.0\nDexterity +3, Attack +1, Pick Pocket +3, Pick Locks +2\nConsumes: 1 Night Hand Gloves, 1 Kosh steel, 1 Glittering Green Eye.\nThe source item can be bought again.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_tg_whisperthorn','Whisperthorn');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_tg_whisperthorn','A guild foil with a blade like a needle. Its owner never raised his voice, nor needed to.\n\n10% on hit: Sundered Guard\n10% on hit: wielder gains Quickstep');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_tg_velane_fang','Velane''s Fang');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_tg_velane_fang','A long dirk with a groove for venom. The Silent Hand of Tallon paid in blood for the one they lost.\n\n15% on hit: Wyrm Venom\n12% on hit: Bleeding');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_tg_shadow_stars','Shadow Stars');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_tg_shadow_stars','Black stars with serrated points, thrown three at a time by those who learned from Velane.\n\n20% on hit: Bleeding');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmTgGloves3_name','Pick Pocket +2, Pick Locks +3');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmTgGloves3_short','Pick Pocket +2, Pick Locks +3');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmTgGloves3_long','Pick Pocket +2, Pick Locks +3');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_tg_gloves3','Shadow Hand Gloves');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_tg_gloves3','The Velvet Hand, rubbed with a burnt firefly sac until it drinks the light. A blade in it never misses its moment.\n\nDexterity +3, Attack +1, Parry +1, Dodge +1, Pick Pocket +4, Pick Locks +3');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_rezept_tg_gloves3','Plans: Shadow Hand Gloves');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_rezept_tg_gloves3','Bowcraft 11. Makes Shadow Hand Gloves.\nArms 3; leather, encumbrance 0.0\nDexterity +3, Attack +1, Parry +1, Dodge +1, Pick Pocket +4, Pick Locks +3\nConsumes: 1 Velvet Hand Gloves, 1 Firefly Ember Sac, 1 Gold leaf.\nThe source item can be bought again.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmTgFoxMask_name','Pick Pocket +1, Fast Talk +2, Sneak +2');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmTgFoxMask_short','Pick Pocket +1, Fast Talk +2, Sneak +2');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmTgFoxMask_long','Pick Pocket +1, Fast Talk +2, Sneak +2');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_tg_fox_mask','Mask of the Fox');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_tg_fox_mask','A fox-faced half-mask in black silk. Guards remember a pleasant stranger and nothing else.\n\nCharisma +1, Pick Pocket +3, Fast Talk +2, Sneak +2');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmTgGloves4_name','Attack +1, Pick Pocket +3, Pick Locks +4');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmTgGloves4_short','Attack +1, Pick Pocket +3, Pick Locks +4');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmTgGloves4_long','Attack +1, Pick Pocket +3, Pick Locks +4');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_tg_gloves4','Hands of Phex');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_tg_gloves4','The Shadow Hand, reforged by a dwarf who swore he never touched them. Phex himself would check his purse.\n\nDexterity +4, Agility +1, Attack +2, Parry +1, Dodge +1, Pick Pocket +5, Pick Locks +4');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_rezept_tg_gloves4','Plans: Hands of Phex');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_rezept_tg_gloves4','Bowcraft 13. Makes Hands of Phex.\nArms 4; leather, encumbrance 0.0\nDexterity +4, Agility +1, Attack +2, Parry +1, Dodge +1, Pick Pocket +5, Pick Locks +4\nConsumes: 1 Shadow Hand Gloves, 1 Dwarven steel, 2 Gemstones.\nUNIQUE: the original cannot be bought again.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmTgFoxBoots_name','Sneak +4');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmTgFoxBoots_short','Sneak +4');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmTgFoxBoots_long','Sneak +4');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_tg_fox_boots','Steps of the Fox');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_tg_fox_boots','Iryan boots that a forger swears belonged to a saint. Nobody has ever heard them walk.\n\nAgility +2, Dodge +2, Sneak +4');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmTgPhexWink_name','Pick Pocket +1, Pick Locks +2');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmTgPhexWink_short','Pick Pocket +1, Pick Locks +2');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmTgPhexWink_long','Pick Pocket +1, Pick Locks +2');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_tg_phex_wink','Phex''s Wink');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_tg_phex_wink','A gold fox with one emerald eye. Luck looks the other way for its enemies.\n\nDexterity +2, Agility +1, Dodge +1, Pick Pocket +3, Pick Locks +2');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_tg_fortune','Fortune''s Edge');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_tg_fortune','A rapier with a coin set in the guard. It turns up heads more often than it should.\n\n15% on hit: Sundered Guard\nAgainst sundered foes: +1d6 damage\n8% on hit: wielder gains Quickstep');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmRkPlate_name','LE +5');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmRkPlate_short','LE +5');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmRkPlate_long','LE +5');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_rk_plate','Ronkwer''s Hauberk');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_rk_plate','Ronkwer''s long mail shirt, the rings doubled over chest and back and riveted by a smith who knew his trade. Lighter than it looks.\n\nLE +5');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_rk_thunderhead','Thunderhead Warhammer');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_rk_thunderhead','A war hammer rebalanced around a bear-claw spike. Easier to swing, harder to stop.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_rezept_rk_thunderhead','Plans: Thunderhead Warhammer');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_rezept_rk_thunderhead','Smithing 8. Makes Thunderhead Warhammer.\n2D6+4 HP, AT +1, PA -1, INI -2\nConsumes: 1 Warhammer, 2 Steel, 1 Bear Claw.\nThe source item can be bought again.');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmHqCrest_name','Ranged combat +3');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmHqCrest_short','Ranged combat +3');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('PeArmHqCrest_long','Ranged combat +3');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_hq_crest','Harpy Queen''s Crest');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_hq_crest','A leather hood crowned with the Harpy Queen''s long storm-grey feathers. The wind tells you where an arrow should go.\n\nRanged combat +3, Dodge +1');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('lookat_arm_rezept_hq_crest','Plans: Harpy Queen''s Crest');
INSERT INTO _Locale ("LocaId","LocaText") VALUES ('infoid_arm_rezept_hq_crest','Bowcraft 10. Makes Harpy Queen''s Crest.\nHead 4; leather, encumbrance 0.6\nRanged combat +3, Dodge +1\nConsumes: 1 Leather Helm, 6 Harpy feathers, 1 Gold leaf.\nThe source item can be bought again.');
